import subprocess, functools, sys, random
FZF='/workspace/executable'
def run(items, query, extra=()):
    inp='\n'.join(items)+'\n'
    cmd=[FZF,'-f',query,'--tiebreak=index','-x']+list(extra)
    p=subprocess.run(cmd,input=inp.encode(),capture_output=True)
    out=p.stdout.decode().splitlines()
    return out
def rank_shuffled(items, query, extra=(), seed=1):
    r=list(items); random.Random(seed).shuffle(r)
    out=run(r,query,extra)
    d={x:i for i,x in enumerate(out)}
    return [(d[x],x) for x in sorted(items,key=lambda x:d[x])]
@functools.lru_cache(maxsize=None)
def compare(x,y,query,extra=()):
    """return 'x>y','x<y','tie'"""
    a=run([x,y],query,extra); b=run([y,x],query,extra)
    if len(a)<2 or len(b)<2: raise ValueError((a,b,x,y,query))
    if a[0]==x and b[0]==y: return 'tie'
    if a[0]==y and b[0]==x: return 'tie'
    if a[0]==x and b[0]==x: return 'x>y'
    if a[0]==y and b[0]==y: return 'x<y'
    return 'unknown'
if __name__=='__main__':
    chars=['x','X','0',' ','-','.','_','a','Z','b','q','z']
    items=['q'+c for c in chars]
    # group ties
    groups=[]
    for it in items:
        placed=False
        for g in groups:
            if compare(it,g[0],'q')=='tie': g.append(it); placed=True; break
        if not placed: groups.append([it])
    for g in groups: print('GROUP:',g)
