{"command": "mkdir -p /tmp/work && cd /tmp/work && cat > algo.go <<'GOEOF'
package main

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// Scoring constants (derived empirically from the reference binary)
const (
	scoreMatch        = 16
	scoreGapStart     = -3
	scoreGapExtension = -1

	bonusBoundaryWhite = scoreMatch / 2 // 8 : whitespace or start of string
	bonusDelimiter     = 7              // ',', '/', ';', ':', '|'
	bonusBoundary      = 6              // other non-word characters
	bonusCamel123      = 5              // camelCase and number-after-letter
	bonusNonWord       = 4              // matched non-word character
	bonusDigitDigit    = -1             // digit after digit
	bonusWordWord      = -2             // word char after word char
)

type scheme int

const (
	schemeDefault scheme = iota
	schemePath
	schemeHistory
)

type charClass int

const (
	charNonWord charClass = iota
	charLower
	charUpper
	charNumber
	charDelimiter
	charSpace
)

const nonBaseCharacter = utf8.RuneSelf + 1

func charClassOfAscii(c rune) charClass {
	if c >= 'a' && c <= 'z' {
		return charLower
	}
	if c >= 'A' && c <= 'Z' {
		return charUpper
	}
	if c >= '0' && c <= '9' {
		return charNumber
	}
	switch c {
	case ',', '/', ';', ':', '|':
		return charDelimiter
	}
	if c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r' {
		return charSpace
	}
	return charNonWord
}

func charClassOfNonAscii(c rune) charClass {
	if unicode.IsNumber(c) {
		return charNumber
	}
	if unicode.IsUpper(c) {
		return charUpper
	}
	if unicode.IsLetter(c) {
		return charLower
	}
	return charNonWord
}

func charClassOf(c rune) charClass {
	if c <= 0x7f {
		return charClassOfAscii(c)
	}
	return charClassOfNonAscii(c)
}

// bonusFor returns the bonus for matching a character of the given class
// preceded by a character of prevClass.
func bonusFor(prevClass, class charClass) int16 {
	if class == charNonWord {
		return bonusNonWord
	}
	switch prevClass {
	case charSpace:
		return bonusBoundaryWhite
	case charDelimiter:
		return bonusDelimiter
	case charNonWord:
		return bonusBoundary
	case charLower:
		if class == charUpper || class == charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	case charUpper:
		if class == charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	case charNumber:
		if class == charNumber {
			return bonusDigitDigit
		}
		return bonusWordWord
	}
	return bonusWordWord
}

func bonusForStart(class charClass) int16 {
	if class == charNonWord {
		return bonusNonWord
	}
	return bonusBoundaryWhite
}

// bonusAt computes the bonus of text[j] when matched (not consecutive)
func bonusAt(class []charClass, scheme scheme, j int) int16 {
	if scheme == schemeHistory {
		if class[j] == charNonWord {
			return bonusNonWord
		}
		if j == 0 {
			return bonusBoundaryWhite
		}
		switch class[j-1] {
		case charSpace, charDelimiter, charNonWord:
			return bonusBoundaryWhite
		}
		if class[j-1] == charLower && class[j] == charUpper {
			return bonusCamel123
		}
		if class[j] == charNumber && class[j-1] != charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	}
	if scheme == schemePath {
		if j == 0 {
			return bonusBoundaryWhite
		}
		if class[j] == charNonWord {
			return bonusNonWord
		}
		switch class[j-1] {
		case charSpace, charDelimiter, charNonWord:
			if class[j-1] == charDelimiter && class[j-1] == '/' {
				return bonusBoundaryWhite + 1
			}
			return bonusBoundaryWhite
		}
		if class[j-1] == charLower && class[j] == charUpper {
			return bonusCamel123 - 1
		}
		if class[j] == charNumber && class[j-1] != charNumber {
			return bonusCamel123 - 1
		}
		return bonusWordWord
	}
	if j == 0 {
		return bonusForStart(class[j])
	}
	return bonusFor(class[j-1], class[j])
}

func normalizeRune(r rune) rune {
	if r < 0x80 {
		return r
	}
	if n, ok := normalizeMap[r]; ok {
		return n
	}
	return r
}

var normalizeMap = buildNormalizeMap()

func buildNormalizeMap() map[rune]rune {
	m := map[rune]rune{}
	// Latin-1 supplement and Latin Extended-A: strip combining accents of the
	// base letters a-z / A-Z by decomposing.
	for base, comb := range map[rune][]rune{
		'A': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030A', '\u0304', '\u0306', '\u0327'},
		'a': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030A', '\u0304', '\u0306', '\u0327'},
		'E': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'e': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'I': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'i': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'O': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030B', '\u0327'},
		'o': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030B', '\u0327'},
		'U': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'u': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'Y': {'\u0301'},
		'y': {'\u0301'},
		'N': {'\u0303'},
		'n': {'\u0303'},
		'C': {'\u0327'},
		'c': {'\u0327'},
		'S': {'\u0327'},
		's': {'\u0327'},
		'Z': {'\u0307'},
		'z': {'\u0307'},
		'D': {'\u0307'},
		'd': {'\u0307'},
		'G': {'\u0306'},
		'g': {'\u0306'},
		'H': {'\u030A'},
		'h': {'\u030A'},
		'L': {'\u0304'},
		'l': {'\u0304'},
		'T': {'\u0307'},
		't': {'\u0307'},
	} {
		for _, c := range comb {
			m[base+c] = base
		}
	}
	return m
}

// Result of a match
type Result struct {
	Start int32
	End   int32
	Score int32
}

var missResult = Result{Start: -1, End: 0, Score: 0}

func isMiss(r Result) bool { return r.Start < 0 }

// ---------------------------------------------------------------- fuzzy v2

// FuzzyMatchV2 finds the optimal match of pat in text.
// Returns the score and the matched positions.
func FuzzyMatchV2(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	if M > N {
		return missResult, nil
	}

	// Pre-compute classes and normalized/case-folded text
	tclass := make([]charClass, N)
	tchar := make([]rune, N)
	pchar := make([]rune, M)
	forward := true
	if !caseSensitive {
		forward = false
	}
	forward = true
	if !forward {
		// reverse handling not needed; fzf scans forward for v2
		forward = true
	}
	for i := 0; i < N; i++ {
		c := text[i]
		class := charClassOf(c)
		if !caseSensitive && class == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		tchar[i] = c
		tclass[i] = class
	}
	for i := 0; i < M; i++ {
		c := pat[i]
		class := charClassOf(c)
		if !caseSensitive && class == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		pchar[i] = c
	}

	bonus0 := make([]int16, N)
	for j := 0; j < N; j++ {
		bonus0[j] = bonusAt(tclass, schemeDefault, j)
	}

	const nb = 7 // number of distinct bonus values
	bvals := []int16{bonusBoundaryWhite, bonusDelimiter, bonusBoundary, bonusCamel123, bonusNonWord, bonusDigitDigit, bonusWordWord}
	bidx := map[int16]int{}
	for i, v := range bvals {
		bidx[v] = i
	}

	minusInf := int32(-1) << 30
	// f[j][b] = best score of matching pat[:i] with the last matched char at j and bonus b
	cur := make([][]int32, N)
	prev := make([][]int32, N)
	for j := 0; j < N; j++ {
		cur[j] = make([]int32, nb)
		prev[j] = make([]int32, nb)
		for b := 0; b < nb; b++ {
			cur[j][b] = minusInf
			prev[j][b] = minusInf
		}
	}
	// backtracking pointers
	type bt struct{ j, b, pj, pb int }
	// We store backpointers for the "skip" transition only; the match
	// transition is (j-1, same b).
	prevMatch := make([][]bt, N)

	// i = 0
	for j := 0; j < N; j++ {
		if tchar[j] != pchar[0] {
			continue
		}
		b := bonus0[j]
		bi := bidx[b]
		v := int32(scoreMatch) + int32(b)*2
		if v > cur[j][bi] {
			cur[j][bi] = v
		}
	}
	if M == 1 {
		best, bj := int32(minusInf), -1
		for j := 0; j < N; j++ {
			for b := 0; b < nb; b++ {
				if cur[j][b] > best {
					best = cur[j][b]
					bj = j
				}
			}
		}
		if bj < 0 {
			return missResult, nil
		}
		positions := []int{bj}
		return Result{Start: int32(bj), End: int32(bj + 1), Score: best}, positions
	}

	// prefix max of (best score + j) for skip transitions
	for i := 1; i < M; i++ {
		// swap
		cur, prev = prev, cur
		for j := 0; j < N; j++ {
			for b := 0; b < nb; b++ {
				cur[j][b] = minusInf
			}
			prevMatch[j] = nil
		}
		// prefix max
		pmax := minusInf
		pmaxJ := -1
		pmaxArr := make([]int32, N)
		pmaxIdx := make([]int, N)
		for j := 0; j < N; j++ {
			best := minusInf
			for b := 0; b < nb; b++ {
				if prev[j][b] > best {
					best = prev[j][b]
				}
			}
			if best > minusInf/2 {
				if best+int32(j) > pmax {
					pmax = best + int32(j)
					pmaxJ = j
				}
			}
			pmaxArr[j] = pmax
			pmaxIdx[j] = pmaxJ
		}
		for j := i; j < N; j++ {
			if tchar[j] != pchar[i] {
				continue
			}
			b0 := bonus0[j]
			bi0 := bidx[b0]
			// non-consecutive transitions: j' <= j-2
			var fromJ, fromB = -1, 0
			bestVal := minusInf
			if j-2 >= 0 && pmaxArr[j-2] > minusInf/2 {
				v := pmaxArr[j-2] - int32(j) - 1
				if v > bestVal {
					bestVal = v
					fromJ = pmaxIdx[j-2]
				}
			}
			if bestVal > minusInf/2 {
				v := bestVal + int32(scoreMatch) + int32(b0)
				if v > cur[j][bi0] {
					cur[j][bi0] = v
					prevMatch[j] = append(prevMatch[j], bt{j, bi0, fromJ, -1})
				}
			}
			// consecutive transition from j-1
			if j-1 >= i-1 {
				for b := 0; b < nb; b++ {
					if prev[j-1][b] > minusInf/2 {
						v := prev[j-1][b] + int32(scoreMatch) + int32(bvals[b])
						if v > cur[j][b] {
							cur[j][b] = v
						}
					}
				}
			}
		}
		if i == M-1 {
			break
		}
	}
	// final: find best over all j and b
	best, bestJ, bestB := int32(minusInf), -1, 0
	for j := M - 1; j < N; j++ {
		for b := 0; b < nb; b++ {
			if cur[j][b] > best {
				best = cur[j][b]
				bestJ = j
				bestB = b
			}
		}
	}
	if bestJ < 0 {
		return missResult, nil
	}
	positions := make([]int, 0, M)
	// backtrace
	j := bestJ
	for i := M - 1; i >= 0; i-- {
		positions = append(positions, j)
		if i == 0 {
			break
		}
		// find the previous position: either j-1 (sticky) with bonus b, or
		// some j' < j-1 with bonus0
		target := cur[j][bestB] - int32(scoreMatch) - int32(bvals[bestB])
		if j-1 >= i-1 && prev[j-1][bestB] == target {
			j = j - 1
			// prev is the array for i-1
			cur, prev = prev, cur
			continue
		}
		// non-consecutive: find j' such that prev[j'][b] + penalty == target
		found := false
		for pj := i - 1; pj <= j-2; pj++ {
			for b := 0; b < nb; b++ {
				if prev[pj][b] > minusInf/2 && prev[pj][b]+int32(-(j-pj+1))+int32(scoreMatch)+int32(bvals[bestB]) == target {
					j = pj
					bestB = b
					cur, prev = prev, cur
					found = true
					break
				}
			}
			if found {
				break
			}
		}
		if !found {
			break
		}
	}
	// reverse
	for l, r := 0, len(positions)-1; l < r; l, r = l+1, r-1 {
		positions[l], positions[r] = positions[r], positions[l]
	}
	start, end := positions[0], positions[len(positions)-1]+1
	return Result{Start: int32(start), End: int32(end), Score: best}, positions
}

// ---------------------------------------------------------------- fuzzy v1

// FuzzyMatchV1 greedy matching (used as a fallback for very large inputs)
func FuzzyMatchV1(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 || M > N {
		return missResult, nil
	}
	tchar := make([]rune, N)
	tclass := make([]charClass, N)
	for i := 0; i < N; i++ {
		c := text[i]
		class := charClassOf(c)
		if !caseSensitive && class == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		tchar[i] = c
		tclass[i] = class
	}
	pchar := make([]rune, M)
	for i := 0; i < M; i++ {
		c := pat[i]
		class := charClassOf(c)
		if !caseSensitive && class == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		pchar[i] = c
	}
	// greedy: first occurrence of each pattern char
	idx := 0
	positions := make([]int, 0, M)
	for i := 0; i < M; i++ {
		found := false
		for j := idx; j < N; j++ {
			if tchar[j] == pchar[i] {
				positions = append(positions, j)
				idx = j + 1
				found = true
				break
			}
		}
		if !found {
			return missResult, nil
		}
	}
	// score
	score := int32(0)
	prev := -2
	var lastBonus int16
	for k, p := range positions {
		var b int16
		if p == prev+1 && k > 0 {
			b = lastBonus
		} else {
			b = bonusAt(tclass, schemeDefault, p)
		}
		if k == 0 {
			b *= 2
		}
		if k > 0 {
			gap := p - prev - 1
			if gap > 0 {
				score += int32(scoreGapStart) + int32(gap-1)*int32(scoreGapExtension)
			}
		}
		score += int32(scoreMatch) + int32(b)
		lastBonus = b
		prev = p
	}
	positions = trimGaps(positions)
	return Result{Start: int32(positions[0]), End: int32(positions[len(positions)-1] + 1), Score: score}, positions
}

func trimGaps(pos []int) []int {
	if len(pos) == 0 {
		return pos
	}
	out := []int{pos[0]}
	for _, p := range pos[1:] {
		if p > out[len(out)-1] {
			out = append(out, p)
		}
	}
	return out
}

// ------------------------------------------------------------- exact etc.

func exactMatch(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	tchar := foldText(text, caseSensitive, normalize)
	pchar := foldText(pat, caseSensitive, normalize)
	idx := indexOf(tchar, pchar, 0)
	if idx < 0 {
		return missResult, nil
	}
	return Result{Start: int32(idx), End: int32(idx + M), Score: 0}, nil
}

func foldText(text []rune, caseSensitive, normalize bool) []rune {
	out := make([]rune, len(text))
	for i, c := range text {
		class := charClassOf(c)
		if !caseSensitive && class == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		out[i] = c
	}
	return out
}

func indexOf(text, pat []rune, from int) int {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return from
	}
	if M > N {
		return -1
	}
outer:
	for i := from; i <= N-M; i++ {
		for j := 0; j < M; j++ {
			if text[i+j] != pat[j] {
				continue outer
			}
		}
		return i
	}
	return -1
}

// prefixMatch checks that text starts with pat
func prefixMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	if len(p) == 0 {
		return Result{0, 0, 0}, nil
	}
	if len(t) < len(p) {
		return missResult, nil
	}
	for i := 0; i < len(p); i++ {
		if t[i] != p[i] {
			return missResult, nil
		}
	}
	return Result{Start: 0, End: int32(len(p)), Score: 0}, nil
}

func suffixMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	M := len(p)
	N := len(t)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	if M > N {
		return missResult, nil
	}
	for i := 0; i < M; i++ {
		if t[N-M+i] != p[i] {
			return missResult, nil
		}
	}
	return Result{Start: int32(N - M), End: int32(N), Score: 0}, nil
}

func equalMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	if len(t) != len(p) {
		return missResult, nil
	}
	for i := range t {
		if t[i] != p[i] {
			return missResult, nil
		}
	}
	return Result{Start: 0, End: int32(len(p)), Score: 0}, nil
}

// whitespace-aware helpers for boundary matching
func isWordChar(c rune) bool { return charClassOf(c) != charNonWord }

func boundaryMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	M := len(p)
	N := len(t)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	var best Result = missResult
	from := 0
	for {
		idx := indexOf(t, p, from)
		if idx < 0 {
			break
		}
		from = idx + 1
		okBefore := idx == 0 || !isWordRune(text[idx-1])
		okAfter := idx+M >= N || !isWordRune(text[idx+M])
		if okBefore && okAfter {
			r := Result{Start: int32(idx), End: int32(idx + M)}
			if isMiss(best) || r.Start < best.Start {
				best = r
			}
			break
		}
	}
	return best, nil
}

func isWordRune(c rune) bool {
	if c <= 0x7f {
		switch charClassOfAscii(c) {
		case charLower, charUpper, charNumber:
			return true
		}
		return false
	}
	switch charClassOfNonAscii(c) {
	case charLower, charUpper, charNumber:
		return true
	}
	return false
}

