package main

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// Scoring constants (derived empirically from the reference binary)
const (
	scoreMatch        = 16
	scoreGapStart     = -3
	scoreGapExtension = -1

	bonusBoundaryWhite = scoreMatch / 2 // 8 : whitespace or start of string
	bonusDelimiter     = 7              // ',', '/', ';', ':', '|'
	bonusBoundary      = 6              // other non-word characters
	bonusCamel123      = 5              // camelCase and number-after-letter
	bonusNonWord       = 4              // matched non-word character
	bonusDigitDigit    = -1             // digit after digit
	bonusWordWord      = -2             // word char after word char
)

type scheme int

const (
	schemeDefault scheme = iota
	schemePath
	schemeHistory
)

type charClass int

const (
	charNonWord charClass = iota
	charLower
	charUpper
	charNumber
	charDelimiter
	charSpace
)

const nonBaseCharacter = utf8.RuneSelf + 1

func charClassOfAscii(c rune) charClass {
	if c >= 'a' && c <= 'z' {
		return charLower
	}
	if c >= 'A' && c <= 'Z' {
		return charUpper
	}
	if c >= '0' && c <= '9' {
		return charNumber
	}
	switch c {
	case ',', '/', ';', ':', '|':
		return charDelimiter
	}
	if c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r' {
		return charSpace
	}
	return charNonWord
}

func charClassOfNonAscii(c rune) charClass {
	if unicode.IsNumber(c) {
		return charNumber
	}
	if unicode.IsUpper(c) {
		return charUpper
	}
	if unicode.IsLetter(c) {
		return charLower
	}
	return charNonWord
}

func charClassOf(c rune) charClass {
	if c <= 0x7f {
		return charClassOfAscii(c)
	}
	return charClassOfNonAscii(c)
}

// bonusFor returns the bonus for matching a character of the given class
// preceded by a character of prevClass.
func bonusFor(prevClass, class charClass) int16 {
	if class == charNonWord {
		return bonusNonWord
	}
	switch prevClass {
	case charSpace:
		return bonusBoundaryWhite
	case charDelimiter:
		return bonusDelimiter
	case charNonWord:
		return bonusBoundary
	case charLower:
		if class == charUpper || class == charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	case charUpper:
		if class == charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	case charNumber:
		if class == charNumber {
			return bonusDigitDigit
		}
		return bonusWordWord
	}
	return bonusWordWord
}

func bonusForStart(class charClass) int16 {
	if class == charNonWord {
		return bonusNonWord
	}
	return bonusBoundaryWhite
}

// bonusAt computes the bonus of text[j] when matched (not consecutive)
func bonusAt(class []charClass, scheme scheme, j int) int16 {
	if scheme == schemeHistory {
		if class[j] == charNonWord {
			return bonusNonWord
		}
		if j == 0 {
			return bonusBoundaryWhite
		}
		switch class[j-1] {
		case charSpace, charDelimiter, charNonWord:
			return bonusBoundaryWhite
		}
		if class[j-1] == charLower && class[j] == charUpper {
			return bonusCamel123
		}
		if class[j] == charNumber && class[j-1] != charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	}
	if scheme == schemePath {
		if j == 0 {
			return bonusBoundaryWhite
		}
		if class[j] == charNonWord {
			return bonusNonWord
		}
		switch class[j-1] {
		case charSpace, charDelimiter, charNonWord:
			if class[j-1] == charDelimiter && class[j-1] == '/' {
				return bonusBoundaryWhite + 1
			}
			return bonusBoundaryWhite
		}
		if class[j-1] == charLower && class[j] == charUpper {
			return bonusCamel123 - 1
		}
		if class[j] == charNumber && class[j-1] != charNumber {
			return bonusCamel123 - 1
		}
		return bonusWordWord
	}
	if j == 0 {
		return bonusForStart(class[j])
	}
	return bonusFor(class[j-1], class[j])
}

func normalizeRune(r rune) rune {
	if r < 0x80 {
		return r
	}
	if n, ok := normalizeMap[r]; ok {
		return n
	}
	return r
}

var normalizeMap = buildNormalizeMap()

func buildNormalizeMap() map[rune]rune {
	m := map[rune]rune{}
	// Latin-1 supplement and Latin Extended-A: strip combining accents of the
	// base letters a-z / A-Z by decomposing.
	for base, comb := range map[rune][]rune{
		'A': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030A', '\u0304', '\u0306', '\u0327'},
		'a': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030A', '\u0304', '\u0306', '\u0327'},
		'E': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'e': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'I': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'i': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'O': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030B', '\u0327'},
		'o': {'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030B', '\u0327'},
		'U': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'u': {'\u0300', '\u0301', '\u0302', '\u0308'},
		'Y': {'\u0301'},
		'y': {'\u0301'},
		'N': {'\u0303'},
		'n': {'\u0303'},
		'C': {'\u0327'},
		'c': {'\u0327'},
		'S': {'\u0327'},
		's': {'\u0327'},
		'Z': {'\u0307'},
		'z': {'\u0307'},
		'D': {'\u0307'},
		'd': {'\u0307'},
		'G': {'\u0306'},
		'g': {'\u0306'},
		'H': {'\u030A'},
		'h': {'\u030A'},
		'L': {'\u0304'},
		'l': {'\u0304'},
		'T': {'\u0307'},
		't': {'\u0307'},
	} {
		for _, c := range comb {
			m[base+c] = base
		}
	}
	return m
}

// Result of a match
type Result struct {
	Start int32
	End   int32
	Score int32
}

var missResult = Result{Start: -1, End: 0, Score: 0}

func isMiss(r Result) bool { return r.Start < 0 }

// ---------------------------------------------------------------- fuzzy v2

// FuzzyMatchV2 finds the optimal match of pat in text.
// Returns the score and the matched positions.
func FuzzyMatchV2(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	if M > N {
		return missResult, nil
	}

	// Pre-compute classes and normalized/case-folded text
	tclass := make([]charClass, N)
	tchar := make([]rune, N)
	pchar := make([]rune, M)
	forward := true
	if !caseSensitive {
