type Result struct {
	Start int32
	End   int32
	Score int32
}

var missResult = Result{Start: -1, End: 0, Score: 0}

func isMiss(r Result) bool { return r.Start < 0 }

// ---------------------------------------------------------------------------
// Fuzzy matching (v2 - optimal)
// ---------------------------------------------------------------------------

// The set of bonus values that can propagate through the "sticky" rule
// (a character matched right after another matched character inherits the
// previous character's bonus).
var bonusVals = []int16{bonusBoundaryWhite, bonusDelimiter, bonusBoundary,
	bonusCamel123, bonusNonWord, bonusDigitDigit, bonusWordWord}

const numBonus = len(bonusVals)

func bonusIndex(v int16) int {
	for i, x := range bonusVals {
		if x == v {
			return i
		}
	}
	return 0
}

func foldAndClass(text []rune, caseSensitive, normalize bool) ([]rune, []charClass) {
	n := len(text)
	chars := make([]rune, n)
	class := make([]charClass, n)
	for i := 0; i < n; i++ {
		c := text[i]
		cl := charClassOf(c)
		if !caseSensitive && cl == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		chars[i] = c
		class[i] = cl
	}
	return chars, class
}

const int16Min = int32(-1) << 28

// FuzzyMatchV2 finds the optimal match of pat in text.
func FuzzyMatchV2(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	if M > N {
		return missResult, nil
	}
	tchar, tclass := foldAndClass(text, caseSensitive, normalize)
	pchar, _ := foldAndClass(pat, caseSensitive, normalize)

	bonus0 := make([]int16, N)
	for j := 0; j < N; j++ {
		bonus0[j] = bonusAt(tclass, schemeDefault, j)
	}

	// layer[j*numBonus+b]
	newLayer := func() []int32 {
		a := make([]int32, N*numBonus)
		for i := range a {
			a[i] = int16Min
		}
		return a
	}
	cur := newLayer()
	// i == 0
	for j := 0; j < N; j++ {
		if tchar[j] != pchar[0] {
			continue
		}
		b := bonus0[j]
		bi := bonusIndex(b)
		v := int32(scoreMatch) + int32(b)*2
		if v > cur[j*numBonus+bi] {
			cur[j*numBonus+bi] = v
		}
	}
	layers := make([]layer, 0, M)
	if M == 1 {
		best, bj := int32(int16Min), -1
		for j := 0; j < N; j++ {
			for b := 0; b < numBonus; b++ {
				if v := cur[j*numBonus+b]; v > best {
					best, bj = v, j
				}
			}
		}
		if bj < 0 {
			return missResult, nil
		}
		return Result{Start: int32(bj), End: int32(bj + 1), Score: best}, []int{bj}
	}

	for i := 1; i < M; i++ {
		nxt := newLayer()
		prevPos := make([]int32, N*numBonus)
		prevBonus := make([]int8, N*numBonus)
		for k := range prevPos {
			prevPos[k] = -1
		}
		pmax := int32(int16Min)
		pmaxJ := int32(-1)
		pmaxArr := make([]int32, N)
		pmaxIdx := make([]int32, N)
		for j := 0; j < N; j++ {
			best := int32(int16Min)
			for b := 0; b < numBonus; b++ {
				if v := cur[j*numBonus+b]; v > best {
					best = v
				}
			}
			if best > int16Min/2 && best+int32(j) > pmax {
				pmax = best + int32(j)
				pmaxJ = int32(j)
			}
			pmaxArr[j] = pmax
			pmaxIdx[j] = pmaxJ
		}
		for j := i; j < N; j++ {
			if tchar[j] != pchar[i] {
				continue
			}
			b0 := bonus0[j]
			bi0 := bonusIndex(b0)
			if j >= 2 {
				if pj := pmaxIdx[j-2]; pj >= 0 {
					v := pmaxArr[j-2] - int32(j) - 1 + int32(scoreMatch) + int32(b0)
					k := j*numBonus + bi0
					if v > nxt[k] {
						nxt[k] = v
						prevPos[k] = pj
						prevBonus[k] = -1
					}
				}
			}
			if j-1 >= i-1 {
				for b := 0; b < numBonus; b++ {
					if v := cur[(j-1)*numBonus+b]; v > int16Min/2 {
						nv := v + int32(scoreMatch) + int32(bonusVals[b])
						k := j*numBonus + b
						if nv > nxt[k] {
							nxt[k] = nv
							prevPos[k] = int32(j - 1)
							prevBonus[k] = int8(b)
						}
					}
				}
			}
		}
		layers = append(layers, layer{cur: nxt, prevPos: prevPos, prevBonus: prevBonus})
		cur = nxt
	}

	best, bestJ, bestB := int32(int16Min), -1, 0
	for j := M - 1; j < N; j++ {
		for b := 0; b < numBonus; b++ {
			if v := cur[j*numBonus+b]; v > best {
				best, bestJ, bestB = v, j, b
			}
		}
	}
	if bestJ < 0 {
		return missResult, nil
	}
	positions := make([]int, 0, M)
	j, b := bestJ, bestB
	for i := M - 1; i >= 0; i-- {
		positions = append(positions, j)
		if i == 0 {
			break
		}
		snap := layers[i-1]
		k := j*numBonus + b
		pj := snap.prevPos[k]
		pb := snap.prevBonus[k]
		j = int(pj)
		if pb >= 0 {
			b = int(pb)
		} else {
			b = bonusIndex(bonus0[j])
		}
	}
	for l, r := 0, len(positions)-1; l < r; l, r = l+1, r-1 {
		positions[l], positions[r] = positions[r], positions[l]
	}
	start, end := positions[0], positions[len(positions)-1]+1
	return Result{Start: int32(start), End: int32(end), Score: best}, positions
}

type layer struct {
	cur       []int32
	prevPos   []int32
	prevBonus []int8
}

// ---------------------------------------------------------------------------
// Fuzzy matching (v1 - greedy), used for very large inputs
// ---------------------------------------------------------------------------

func FuzzyMatchV1(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 || M > N {
		return missResult, nil
	}
	tchar, tclass := foldAndClass(text, caseSensitive, normalize)
	pchar, _ := foldAndClass(pat, caseSensitive, normalize)
	idx := 0
	positions := make([]int, 0, M)
	for i := 0; i < M; i++ {
		found := false
		for j := idx; j < N; j++ {
			if tchar[j] == pchar[i] {
				positions = append(positions, j)
				idx = j + 1
				found = true
				break
			}
		}
		if !found {
			return missResult, nil
		}
	}
	score := int32(0)
	prev := -2
	var lastBonus int16
	for k, p := range positions {
		var b int16
		if p == prev+1 && k > 0 {
			b = lastBonus
		} else {
			b = bonusAt(tclass, schemeDefault, p)
		}
		if k == 0 {
			b *= 2
		}
