}

func exactMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	M := len(pat)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	idx := indexOf(t, p, 0)
	if idx < 0 {
