package main

import (
	"unicode"
	"unicode/utf8"
)

// ---------------------------------------------------------------------------
// Scoring constants (derived empirically from the reference implementation)
// ---------------------------------------------------------------------------

const (
	scoreMatch        = 16
	scoreGapStart     = -3
	scoreGapExtension = -1

	bonusBoundaryWhite = scoreMatch / 2 // 8  : whitespace or start of string
	bonusDelimiter     = 7              // ',', '/', ';', ':', '|'
	bonusBoundary      = 6              // other non-word characters
	bonusCamel123      = 5              // camelCase / number after letter
	bonusNonWord       = 4              // matched non-word character
	bonusDigitDigit    = -1             // digit after digit
	bonusWordWord      = -2             // word char after word char
)

type scheme int

const (
	schemeDefault scheme = iota
	schemePath
	schemeHistory
)

type charClass int

const (
	charNonWord charClass = iota
	charLower
	charUpper
	charNumber
	charDelimiter
	charSpace
)

const nonBaseCharacter = utf8.RuneSelf + 1

func charClassOfAscii(c rune) charClass {
	if c >= 'a' && c <= 'z' {
		return charLower
	}
	if c >= 'A' && c <= 'Z' {
		return charUpper
	}
	if c >= '0' && c <= '9' {
		return charNumber
	}
	switch c {
	case ',', '/', ';', ':', '|':
		return charDelimiter
	}
	if c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r' {
		return charSpace
	}
	return charNonWord
}

func charClassOfNonAscii(c rune) charClass {
	if unicode.IsNumber(c) {
		return charNumber
	}
	if unicode.IsUpper(c) {
		return charUpper
	}
	if unicode.IsLetter(c) {
		return charLower
	}
	return charNonWord
}

func charClassOf(c rune) charClass {
	if c <= 0x7f {
		return charClassOfAscii(c)
	}
	return charClassOfNonAscii(c)
}

func isDelimiterRune(c rune) bool {
	return c == ',' || c == '/' || c == ';' || c == ':' || c == '|'
}

func isSpaceRune(c rune) bool {
	switch c {
	case ' ', '\t', '\n', '\v', '\f', '\r':
		return true
	}
	return false
}

// bonusFor returns the bonus for matching a character of the given class
// preceded by a character of prevClass.
func bonusFor(prevClass, class charClass, prev rune) int16 {
	if class == charNonWord {
		return bonusNonWord
	}
	switch prevClass {
	case charSpace:
		return bonusBoundaryWhite
	case charDelimiter:
		return bonusDelimiter
	case charNonWord:
		return bonusBoundary
	case charLower:
		if class == charUpper || class == charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	case charUpper:
		if class == charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	case charNumber:
		if class == charNumber {
			return bonusDigitDigit
		}
		return bonusWordWord
	}
	return bonusWordWord
}

// bonusAt computes the bonus of text[j] when matched (not as a sticky match).
func bonusAt(class []charClass, sc scheme, j int) int16 {
	if j < 0 {
		return bonusBoundaryWhite
	}
	if class[j] == charNonWord {
		return bonusNonWord
	}
	if j == 0 {
		return bonusBoundaryWhite
	}
	switch sc {
	case schemeHistory:
		switch class[j-1] {
		case charSpace, charDelimiter, charNonWord:
			return bonusBoundaryWhite
		}
		if class[j-1] == charLower && class[j] == charUpper {
			return bonusCamel123
		}
		if class[j] == charNumber && class[j-1] != charNumber {
			return bonusCamel123
		}
		return bonusWordWord
	case schemePath:
		switch class[j-1] {
		case charDelimiter:
			return bonusBoundaryWhite + 1
		case charSpace, charNonWord:
			return bonusBoundaryWhite
		}
		if class[j-1] == charLower && class[j] == charUpper {
			return bonusCamel123 - 1
		}
		if class[j] == charNumber && class[j-1] != charNumber {
			return bonusCamel123 - 1
		}
		return bonusWordWord
	}
	return bonusFor(class[j-1], class[j], 0)
}

// ---------------------------------------------------------------------------
// Normalisation
// ---------------------------------------------------------------------------

func normalizeRune(r rune) rune {
	if r < 0x80 {
		return r
	}
	if n, ok := normalizeMap[r]; ok {
		return n
	}
	return r
}

var normalizeMap = buildNormalizeMap()

func buildNormalizeMap() map[rune]rune {
	m := map[rune]rune{}
	type pair struct {
		base rune
		comb []rune
	}
	pairs := []pair{
		{'A', []rune{'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030A', '\u0304', '\u0306', '\u0327', '\u0328'}},
		{'a', []rune{'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030A', '\u0304', '\u0306', '\u0327', '\u0328'}},
		{'E', []rune{'\u0300', '\u0301', '\u0302', '\u0308'}},
		{'e', []rune{'\u0300', '\u0301', '\u0302', '\u0308'}},
		{'I', []rune{'\u0300', '\u0301', '\u0302', '\u0308'}},
		{'i', []rune{'\u0300', '\u0301', '\u0302', '\u0308'}},
		{'O', []rune{'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030B', '\u0327', '\u0328'}},
		{'o', []rune{'\u0300', '\u0301', '\u0302', '\u0303', '\u0308', '\u030B', '\u0327', '\u0328'}},
		{'U', []rune{'\u0300', '\u0301', '\u0302', '\u0308'}},
		{'u', []rune{'\u0300', '\u0301', '\u0302', '\u0308'}},
		{'Y', []rune{'\u0301'}},
		{'y', []rune{'\u0301'}},
		{'N', []rune{'\u0303'}},
		{'n', []rune{'\u0303'}},
		{'C', []rune{'\u0327'}},
		{'c', []rune{'\u0327'}},
		{'S', []rune{'\u0327'}},
		{'s', []rune{'\u0327'}},
		{'Z', []rune{'\u0307'}},
		{'z', []rune{'\u0307'}},
		'D', []rune{'\u0307'},
		{'d', []rune{'\u0307'}},
		{'G', []rune{'\u0306'}},
		{'g', []rune{'\u0306'}},
		{'H', []rune{'\u030A'}},
		{'h', []rune{'\u030A'}},
		{'L', []rune{'\u0304'}},
		{'l', []rune{'\u0304'}},
		{'T', []rune{'\u0307'}},
		{'t', []rune{'\u0307'}},
	}
	for _, p := range pairs {
		for _, c := range p.comb {
			m[p.base+c] = p.base
		}
	}
	return m
}

// ---------------------------------------------------------------------------
// Results
// ---------------------------------------------------------------------------

type Result struct {
	Start int32
	End   int32
	Score int32
}

var missResult = Result{Start: -1, End: 0, Score: 0}

func isMiss(r Result) bool { return r.Start < 0 }

// ---------------------------------------------------------------------------
// Fuzzy matching (v2 - optimal)
// ---------------------------------------------------------------------------

// The set of bonus values that can propagate through the "sticky" rule
// (a character matched right after another matched character inherits the
// previous character's bonus).
var bonusVals = []int16{bonusBoundaryWhite, bonusDelimiter, bonusBoundary,
	bonusCamel123, bonusNonWord, bonusDigitDigit, bonusWordWord}

const numBonus = len(bonusVals)

func bonusIndex(v int16) int {
	for i, x := range bonusVals {
		if x == v {
			return i
		}
	}
	return 0
}

func foldAndClass(text []rune, caseSensitive, normalize bool) ([]rune, []charClass) {
	n := len(text)
	chars := make([]rune, n)
	class := make([]charClass, n)
	for i := 0; i < n; i++ {
		c := text[i]
		cl := charClassOf(c)
		if !caseSensitive && cl == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		chars[i] = c
		class[i] = cl
	}
	return chars, class
}

const int16Min = int32(-1) << 28

// FuzzyMatchV2 finds the optimal match of pat in text.
func FuzzyMatchV2(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	if M > N {
		return missResult, nil
	}
	tchar, tclass := foldAndClass(text, caseSensitive, normalize)
	pchar, _ := foldAndClass(pat, caseSensitive, normalize)

	bonus0 := make([]int16, N)
	for j := 0; j < N; j++ {
		bonus0[j] = bonusAt(tclass, schemeDefault, j)
	}

	// layer[j*numBonus+b]
	newLayer := func() []int32 {
		a := make([]int32, N*numBonus)
		for i := range a {
			a[i] = int16Min
		}
		return a
	}
	cur := newLayer()
	// i == 0
	for j := 0; j < N; j++ {
		if tchar[j] != pchar[0] {
			continue
		}
		b := bonus0[j]
		bi := bonusIndex(b)
		v := int32(scoreMatch) + int32(b)*2
		if v > cur[j*numBonus+bi] {
			cur[j*numBonus+bi] = v
		}
	}
	layers := make([]layer, 0, M)
	if M == 1 {
		best, bj := int32(int16Min), -1
		for j := 0; j < N; j++ {
			for b := 0; b < numBonus; b++ {
				if v := cur[j*numBonus+b]; v > best {
					best, bj = v, j
				}
			}
		}
		if bj < 0 {
			return missResult, nil
		}
		return Result{Start: int32(bj), End: int32(bj + 1), Score: best}, []int{bj}
	}

	for i := 1; i < M; i++ {
		nxt := newLayer()
		prevPos := make([]int32, N*numBonus)
		prevBonus := make([]int8, N*numBonus)
		for k := range prevPos {
			prevPos[k] = -1
		}
		pmax := int32(int16Min)
		pmaxJ := int32(-1)
		pmaxArr := make([]int32, N)
		pmaxIdx := make([]int32, N)
		for j := 0; j < N; j++ {
			best := int32(int16Min)
			for b := 0; b < numBonus; b++ {
				if v := cur[j*numBonus+b]; v > best {
					best = v
				}
			}
			if best > int16Min/2 && best+int32(j) > pmax {
				pmax = best + int32(j)
				pmaxJ = int32(j)
			}
			pmaxArr[j] = pmax
			pmaxIdx[j] = pmaxJ
		}
		for j := i; j < N; j++ {
			if tchar[j] != pchar[i] {
				continue
			}
			b0 := bonus0[j]
			bi0 := bonusIndex(b0)
			if j >= 2 {
				if pj := pmaxIdx[j-2]; pj >= 0 {
					v := pmaxArr[j-2] - int32(j) - 1 + int32(scoreMatch) + int32(b0)
					k := j*numBonus + bi0
					if v > nxt[k] {
						nxt[k] = v
						prevPos[k] = pj
						prevBonus[k] = -1
					}
				}
			}
			if j-1 >= i-1 {
				for b := 0; b < numBonus; b++ {
					if v := cur[(j-1)*numBonus+b]; v > int16Min/2 {
						nv := v + int32(scoreMatch) + int32(bonusVals[b])
						k := j*numBonus + b
						if nv > nxt[k] {
							nxt[k] = nv
							prevPos[k] = int32(j - 1)
							prevBonus[k] = int8(b)
						}
					}
				}
			}
		}
		layers = append(layers, layer{cur: nxt, prevPos: prevPos, prevBonus: prevBonus})
		cur = nxt
	}

	best, bestJ, bestB := int32(int16Min), -1, 0
	for j := M - 1; j < N; j++ {
		for b := 0; b < numBonus; b++ {
			if v := cur[j*numBonus+b]; v > best {
				best, bestJ, bestB = v, j, b
			}
		}
	}
	if bestJ < 0 {
		return missResult, nil
	}
	positions := make([]int, 0, M)
	j, b := bestJ, bestB
	for i := M - 1; i >= 0; i-- {
		positions = append(positions, j)
		if i == 0 {
			break
		}
		snap := layers[i-1]
		k := j*numBonus + b
		pj := snap.prevPos[k]
		pb := snap.prevBonus[k]
		j = int(pj)
		if pb >= 0 {
			b = int(pb)
		} else {
			b = bonusIndex(bonus0[j])
		}
	}
	for l, r := 0, len(positions)-1; l < r; l, r = l+1, r-1 {
		positions[l], positions[r] = positions[r], positions[l]
	}
	start, end := positions[0], positions[len(positions)-1]+1
	return Result{Start: int32(start), End: int32(end), Score: best}, positions
}

type layer struct {
	cur       []int32
	prevPos   []int32
	prevBonus []int8
}

// ---------------------------------------------------------------------------
// Fuzzy matching (v1 - greedy), used for very large inputs
// ---------------------------------------------------------------------------

func FuzzyMatchV1(caseSensitive, normalize bool, text []rune, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 || M > N {
		return missResult, nil
	}
	tchar, tclass := foldAndClass(text, caseSensitive, normalize)
	pchar, _ := foldAndClass(pat, caseSensitive, normalize)
	idx := 0
	positions := make([]int, 0, M)
	for i := 0; i < M; i++ {
		found := false
		for j := idx; j < N; j++ {
			if tchar[j] == pchar[i] {
				positions = append(positions, j)
				idx = j + 1
				found = true
				break
			}
		}
		if !found {
			return missResult, nil
		}
	}
	score := int32(0)
	prev := -2
	var lastBonus int16
	for k, p := range positions {
		var b int16
		if p == prev+1 && k > 0 {
			b = lastBonus
		} else {
			b = bonusAt(tclass, schemeDefault, p)
		}
		if k == 0 {
			b *= 2
		}
		if k > 0 {
			gap := p - prev - 1
			if gap > 0 {
				score += int32(scoreGapStart) + int32(gap-1)*int32(scoreGapExtension)
			}
		}
		score += int32(scoreMatch) + int32(b)
		lastBonus = b
		prev = p
	}
	return Result{Start: int32(positions[0]), End: int32(positions[len(positions)-1] + 1), Score: score}, positions
}

// ---------------------------------------------------------------------------
// Exact and anchored matches
// ---------------------------------------------------------------------------

func foldText(text []rune, caseSensitive, normalize bool) []rune {
	out := make([]rune, len(text))
	for i, c := range text {
		cl := charClassOf(c)
		if !caseSensitive && cl == charUpper {
			c += 32
		}
		if normalize {
			c = normalizeRune(c)
		}
		out[i] = c
	}
	return out
}

func indexOf(text, pat []rune, from int) int {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return from
	}
	if M > N {
		return -1
	}
outer:
	for i := from; i <= N-M; i++ {
		for j := 0; j < M; j++ {
			if text[i+j] != pat[j] {
				continue outer
			}
		}
		return i
	}
	return -1
}

func exactMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	M := len(pat)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	idx := indexOf(t, p, 0)
	if idx < 0 {
		return missResult, nil
	}
	return Result{Start: int32(idx), End: int32(idx + M), Score: 0}, nil
}

func prefixMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	if len(p) == 0 {
		return Result{0, 0, 0}, nil
	}
	if len(t) < len(p) {
		return missResult, nil
	}
	for i := 0; i < len(p); i++ {
		if t[i] != p[i] {
			return missResult, nil
		}
	}
	return Result{Start: 0, End: int32(len(p)), Score: 0}, nil
}

func suffixMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	M, N := len(p), len(t)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	if M > N {
		return missResult, nil
	}
	for i := 0; i < M; i++ {
		if t[N-M+i] != p[i] {
			return missResult, nil
		}
	}
	return Result{Start: int32(N - M), End: int32(N), Score: 0}, nil
}

func equalMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	if len(t) != len(p) {
		return missResult, nil
	}
	for i := range t {
		if t[i] != p[i] {
			return missResult, nil
		}
	}
	return Result{Start: 0, End: int32(len(p)), Score: 0}, nil
}

// boundaryMatch finds an exact occurrence delimited by word boundaries.
func boundaryMatch(caseSensitive, normalize bool, text, pat []rune) (Result, []int) {
	M := len(pat)
	N := len(text)
	if M == 0 {
		return Result{0, 0, 0}, nil
	}
	t := foldText(text, caseSensitive, normalize)
	p := foldText(pat, caseSensitive, normalize)
	from := 0
	best := missResult
	for {
		idx := indexOf(t, p, from)
		if idx < 0 {
			break
		}
		from = idx + 1
		okBefore := idx == 0 || !isWordRune(text[idx-1])
		okAfter := idx+M >= N || !isWordRune(text[idx+M])
		if okBefore && okAfter {
			return Result{Start: int32(idx), End: int32(idx + M), Score: 0}, nil
		}
	}
	return best, nil
}

func isWordRune(c rune) bool {
	switch charClassOf(c) {
	case charLower, charUpper, charNumber:
		return true
	}
	return false
}
