package main

import (
	"regexp"
	"strings"
)

// ---------------------------------------------------------------------------
// Field index expressions
// ---------------------------------------------------------------------------

type fieldRange struct {
	begin int
	end   int
}

func parseFieldRange(str string) ([]fieldRange, error) {
	f := func(s string) (fieldRange, error) {
		if s == "" {
			return fieldRange{1, -1}, nil
		}
		if s == ".." {
			return fieldRange{1, -1}, nil
		}
		if strings.HasSuffix(s, "..") {
			n, ok := atoi(s[:len(s)-2])
			if !ok {
				return fieldRange{}, errInvalidFormat(s)
			}
			return fieldRange{n, -1}, nil
		}
		if strings.HasPrefix(s, "..") {
			n, ok := atoi(s[2:])
			if !ok {
				return fieldRange{}, errInvalidFormat(s)
			}
			return fieldRange{1, n}, nil
		}
		if strings.Contains(s, "..") {
			parts := strings.SplitN(s, "..", 2)
			b, ok1 := atoi(parts[0])
			e, ok2 := atoi(parts[1])
			if !ok1 || !ok2 {
				return fieldRange{}, errInvalidFormat(s)
			}
			return fieldRange{b, e}, nil
		}
		n, ok := atoi(s)
		if !ok {
			return fieldRange{}, errInvalidFormat(s)
		}
		return fieldRange{n, n}, nil
	}
	var out []fieldRange
	for _, s := range strings.Split(str, ",") {
		if s == "" {
			return nil, errInvalidFormat(str)
		}
		r, err := f(s)
		if err != nil {
			return nil, err
		}
		if r.begin == 0 || r.end == 0 {
			return nil, errInvalidFormat(s)
		}
		out = append(out, r)
	}
	return out, nil
}

func atoi(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	neg := false
	i := 0
	if s[0] == '-' {
		neg = true
		i = 1
	} else if s[0] == '+' {
		i = 1
	}
	if i >= len(s) {
		return 0, false
	}
	v := 0
