package main

import (
	"regexp"
	"strings"
)

// ---------------------------------------------------------------------------
// Field index expressions
// ---------------------------------------------------------------------------

type fieldRange struct {
	begin int
	end   int
}

func parseFieldRange(str string) ([]fieldRange, error) {
	f := func(s string) (fieldRange, error) {
		if s == "" {
			return fieldRange{1, -1}, nil
		}
		if s == ".." {
			return fieldRange{1, -1}, nil
		}
		if strings.HasSuffix(s, "..") {
			n, ok := atoi(s[:len(s)-2])
			if !ok {
				return fieldRange{}, errInvalidFormat(s)
			}
			return fieldRange{n, -1}, nil
		}
		if strings.HasPrefix(s, "..") {
			n, ok := atoi(s[2:])
			if !ok {
				return fieldRange{}, errInvalidFormat(s)
			}
			return fieldRange{1, n}, nil
		}
		if strings.Contains(s, "..") {
			parts := strings.SplitN(s, "..", 2)
			b, ok1 := atoi(parts[0])
			e, ok2 := atoi(parts[1])
			if !ok1 || !ok2 {
				return fieldRange{}, errInvalidFormat(s)
			}
			return fieldRange{b, e}, nil
		}
		n, ok := atoi(s)
		if !ok {
			return fieldRange{}, errInvalidFormat(s)
		}
		return fieldRange{n, n}, nil
	}
	var out []fieldRange
	for _, s := range strings.Split(str, ",") {
		if s == "" {
			return nil, errInvalidFormat(str)
		}
		r, err := f(s)
		if err != nil {
			return nil, err
		}
		if r.begin == 0 || r.end == 0 {
			return nil, errInvalidFormat(s)
		}
		out = append(out, r)
	}
	return out, nil
}

func atoi(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	neg := false
	i := 0
	if s[0] == '-' {
		neg = true
		i = 1
	} else if s[0] == '+' {
		i = 1
	}
	if i >= len(s) {
		return 0, false
	}
	v := 0
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
		v = v*10 + int(s[i]-'0')
	}
	if neg {
		v = -v
	}
	return v, true
}

type fieldExpr struct {
	ranges []fieldRange
}

// ---------------------------------------------------------------------------
// Item
// ---------------------------------------------------------------------------

type Item struct {
	text        []rune // original text
	orig        string
	// transformed (display) text when --with-nth is used
	transformed []rune
	transformedStr string
	index       int32
	// pre-computed fields for the search scope
	trimmed     []rune
	nthCache    map[string][]rune
}

func (i *Item) String() string { return i.orig }

// ---------------------------------------------------------------------------
// Delimiter / fields
// ---------------------------------------------------------------------------

type splitter struct {
	regex      *regexp.Regexp
	isAwkStyle bool
}

func newSplitter(delimiter string) (*splitter, error) {
	if delimiter == "" {
		return &splitter{isAwkStyle: true}, nil
	}
	re, err := regexp.Compile(delimiter)
	if err != nil {
		return nil, err
	}
	isAwk := delimiter == "" || delimiter == " " || delimiter == "\\s+" || delimiter == "[[:space:]]+"
	return &splitter{regex: re, isAwkStyle: isAwk}, nil
}

// splitFields splits the text into fields. Each field is returned with its
// leading delimiter so that the original text can be reconstructed.
func (s *splitter) split(text string) []string {
	if s.isAwkStyle || s.regex == nil {
		return awkFields(text)
	}
	parts := s.regex.Split(text, -1)
	return parts
}

func awkFields(text string) []string {
	var fields []string
	i := 0
	n := len(text)
	for i < n {
		for i < n && isSpaceByte(text[i]) {
			i++
		}
		if i >= n {
			break
		}
		start := i
		for i < n && !isSpaceByte(text[i]) {
			i++
		}
		fields = append(fields, text[start:i])
	}
	return fields
}

func isSpaceByte(b byte) bool {
	switch b {
	case ' ', '\t', '\n', '\v', '\f', '\r':
		return true
	}
	return false
}

// ---------------------------------------------------------------------------
// ANSI handling
// ---------------------------------------------------------------------------

// stripAnsi removes ANSI escape sequences from a string.
func stripAnsi(s string) string {
	var b strings.Builder
	i := 0
	n := len(s)
	for i < n {
		c := s[i]
		if c == 0x1b && i+1 < n {
			switch s[i+1] {
			case '[':
				// CSI
				j := i + 2
				for j < n {
					c2 := s[j]
					if c2 >= 0x40 && c2 <= 0x7e {
						break
					}
					j++
				}
				if j < n {
					i = j + 1
					continue
				}
				i = n
				continue
			case ']':
				// OSC
				j := i + 2
				for j < n {
					if s[j] == 0x07 {
						break
					}
					if s[j] == 0x1b && j+1 < n && s[j+1] == '\\' {
						j++
						break
					}
					j++
				}
				if j < n {
					i = j + 1
					continue
				}
				i = n
				continue
			case 'P', 'X', '^', '_':
				j := i + 2
				for j < n {
					if s[j] == 0x1b && j+1 < n && s[j+1] == '\\' {
						j++
						break
					}
					j++
				}
				if j < n {
					i = j + 1
					continue
				}
				i = n
				continue
			default:
				i += 2
				continue
			}
		}
		b.WriteByte(c)
		i++
	}
	return b.String()
}
