// leading delimiter so that the original text can be reconstructed.
func (s *splitter) split(text string) []string {
	if s.isAwkStyle || s.regex == nil {
		return awkFields(text)
	}
	parts := s.regex.Split(text, -1)
	return parts
}

func awkFields(text string) []string {
	var fields []string
	i := 0
	n := len(text)
	for i < n {
		for i < n && isSpaceByte(text[i]) {
