				for j < n {
					c2 := s[j]
					if c2 >= 0x40 && c2 <= 0x7e {
						break
					}
					j++
				}
				if j < n {
					i = j + 1
					continue
				}
				i = n
				continue
			case ']':
				// OSC
				j := i + 2
				for j < n {
					if s[j] == 0x07 {
						break
					}
					if s[j] == 0x1b && j+1 < n && s[j+1] == '\\' {
						j++
						break
					}
					j++
				}
				if j < n {
					i = j + 1
					continue
				}
				i = n
				continue
			case 'P', 'X', '^', '_':
				j := i + 2
				for j < n {
					if s[j] == 0x1b && j+1 < n && s[j+1] == '\\' {
						j++
						break
					}
					j++
				}
				if j < n {
					i = j + 1
					continue
				}
				i = n
				continue
			default:
				i += 2
				continue
			}
		}
		b.WriteByte(c)
		i++
	}
	return b.String()
}
