package main

import (
	"strings"
)

type termType int

const (
	termFuzzy termType = iota
	termExact
	termPrefix
	termSuffix
	termEqual
)

type term struct {
	typ           termType
	inv           bool
	text          []rune
	caseSensitive bool
}

type termSet struct {
	terms []*term
}

type pattern struct {
	termSets      []termSet
	caseSensitive bool
	normalize     bool
	scheme        scheme
	// cache
	text string
}

func parseTerms(fuzzy, caseSensitive bool, normalize bool, str string) []termSet {
	str = strings.ReplaceAll(str, "\\ ", "\x00")
	tokens := strings.Split(str, " ")
	termSets := make([]termSet, 0, len(tokens))
	set := termSet{}
	for _, token := range tokens {
		typ, inv, text, ok := parseToken(fuzzy, token)
		if !ok {
			continue
		}
		if typ == termFuzzy && text == "|" && !inv {
			if len(set.terms) > 0 {
				termSets = append(termSets, set)
				set = termSet{}
			}
			continue
		}
		text = strings.ReplaceAll(text, "\x00", " ")
		if len(text) == 0 && !inv {
			continue
		}
		t := &term{typ: typ, inv: inv, text: []rune(text), caseSensitive: caseSensitive}
		set.terms = append(set.terms, t)
	}
	if len(set.terms) > 0 {
		termSets = append(termSets, set)
	}
	return termSets
}

func parseToken(fuzzy bool, token string) (termType, bool, string, bool) {
	typ := termFuzzy
	if !fuzzy {
		typ = termExact
	}
	inv := false
	if strings.HasPrefix(token, "!") {
		inv = true
		token = token[1:]
		if typ == termFuzzy {
			typ = termExact
		}
	}
	if strings.HasPrefix(token, "'") {
		if fuzzy {
			typ = termExact
		} else {
			typ = termFuzzy
		}
		token = token[1:]
		if strings.HasSuffix(token, "'") && len(token) > 1 {
			token = token[:len(token)-1]
			typ = termEqual
		}
	} else if strings.HasPrefix(token, "^") {
		token = token[1:]
		if strings.HasSuffix(token, "$") && len(token) > 0 {
			token = token[:len(token)-1]
			typ = termEqual
		} else {
			typ = termPrefix
		}
	} else if strings.HasSuffix(token, "$") && len(token) > 1 {
		token = token[:len(token)-1]
		typ = termSuffix
	}
	if token == "" && !inv {
		return typ, false, "", false
	}
	return typ, inv, token, true
}

// buildPattern compiles the query into a pattern.
func buildPattern(query string, exact bool, caseSensitive bool, normalize bool, sc scheme) *pattern {
	if !caseSensitive {
		for _, r := range query {
			if unicodeIsUpper(r) {
				caseSensitive = true
				break
			}
		}
	}
	return &pattern{
		termSets:      parseTerms(!exact, caseSensitive, normalize, query),
		caseSensitive: caseSensitive,
		normalize:     normalize,
		scheme:        sc,
		text:          query,
	}
}

func unicodeIsUpper(r rune) bool {
	return r >= 'A' && r <= 'Z'
