	}
	return missResult, nil
}

// matchPattern returns the aggregated result for the given text slice, or a
// miss.
func matchPattern(p *pattern, text []rune) (Result, []int, bool) {
	if len(p.termSets) == 0 {
		return Result{0, 0, 0}, nil, true
	}
	total := int32(0)
