{"command": "cd /tmp/work && cat > merger.go <<'GOEOF'
package main

import "strings"

type criterion int

const (
	critScore criterion = iota
	critLength
	critChunk
	critPathname
	critBegin
	critEnd
	critIndex
)

func parseCriteria(s string) ([]criterion, error) {
	out := []criterion{}
	seen := map[criterion]bool{}
	for _, part := range strings.Split(s, ",") {
		var c criterion
		switch part {
		case "score":
			c = critScore
		case "length":
			c = critLength
		case "chunk":
			c = critChunk
		case "pathname":
			c = critPathname
		case "begin":
			c = critBegin
		case "end":
			c = critEnd
		case "index":
			c = critIndex
		default:
			return nil, errInvalidCriterion(part)
		}
		if seen[c] {
			return nil, errDuplicateCriterion(part)
		}
		seen[c] = true
		out = append(out, c)
	}
	// index is implicitly appended at the end
	if !seen[critIndex] {
		out = append(out, critIndex)
	} else if out[len(out)-1] != critIndex {
		return nil, errInvalidCriterion("index")
	}
	return out, nil
}

type result struct {
	item *Item
	res  Result
	pos  []int
}

// sortResults sorts the results by score and the given criteria.
func sortResults(rs []*result, criteria []criterion, noSort bool) {
	if noSort {
		return
	}
	// insertion sort keeps the order stable for ties
	less := func(a, b *result) bool {
		if a.res.Score != b.res.Score {
			return a.res.Score > b.res.Score
		}
		for _, c := range criteria {
			switch c {
			case critLength:
				al, bl := len([]rune(a.item.displayText())), len([]rune(b.item.displayText()))
				if al != bl {
					return al < bl
				}
			case critChunk:
				al, bl := chunkLen(a), chunkLen(b)
				if al != bl {
					return al < bl
				}
			case critPathname:
				al, bl := pathnameVal(a), pathnameVal(b)
				if al != bl {
					return al > bl
				}
			case critBegin:
				if a.res.Start != b.res.Start {
					return a.res.Start < b.res.Start
				}
			case critEnd:
				if a.res.End != b.res.End {
					return a.res.End < b.res.End
				}
			}
		}
		return a.item.index < b.item.index
	}
	// merge sort for stability and O(n log n)
	mergeSort(rs, less)
}

func mergeSort(rs []*result, less func(a, b *result) bool) {
	if len(rs) < 2 {
		return
	}
	mid := len(rs) / 2
	left := make([]*result, mid)
	right := make([]*result, len(rs)-mid)
	copy(left, rs[:mid])
	copy(right, rs[mid:])
	mergeSort(left, less)
	mergeSort(right, less)
	i, j, k := 0, 0, 0
	for i < len(left) && j < len(right) {
		if less(left[i], right[j]) {
			rs[k] = left[i]
			i++
		} else {
			rs[k] = right[j]
			j++
		}
		k++
	}
	for i < len(left) {
		rs[k] = left[i]
		i++
		k++
	}
	for j < len(right) {
		rs[k] = right[j]
		j++
		k++
	}
}

func chunkLen(r *result) int {
	t := r.item.displayText()
	runes := []rune(t)
	s := int(r.res.Start)
	e := int(r.res.End)
	if s < 0 {
		s = 0
	}
	if e > len(runes) {
		e = len(runes)
	}
	if s >= e {
		return 0
	}
	// expand to whitespace boundaries
	for s > 0 && !isSpaceRune(runes[s-1]) {
		s--
	}
	for e < len(runes) && !isSpaceRune(runes[e]) {
		e++
	}
	return e - s
}

func pathnameVal(r *result) bool {
	t := r.item.displayText()
	runes := []rune(t)
	s := int(r.res.Start)
	if s < 0 {
		s = 0
	}
	if s >= len(runes) {
		return false
	}
	lastSlash := -1
	for i := 0; i < s; i++ {
		if runes[i] == '/' {
			lastSlash = i
		}
	}
	return lastSlash >= 0
}
