type optErr struct{ msg string }

func (e *optErr) Error() string { return e.msg }

func errf(format string, args ...interface{}) error {
	return &optErr{msg: fmt.Sprintf(format, args...)}
}

// ParseOptions parses the given arguments into the options struct.
// src is used to prefix error messages ("$FZF_DEFAULT_OPTS", "" for the
// command line).
func ParseOptions(o *Options, args []string, src string) error {
	o.src = src
	prefix := ""
	if src != "" {
		prefix = src + ": "
	}
	i := 0
	for i < len(args) {
		arg := args[i]
		i++
		if arg == "--" {
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			// negation
			if strings.HasPrefix(name, "no-") {
				base := name[3:]
				if err := handleNegation(o, base, hasValue, value); err != nil {
					return errf("%s%v", prefix, err)
				}
				continue
			}
			if err := handleOption(o, name, hasValue, value, args, &i); err != nil {
				if err == errUnknownOption {
					return errf("%sunknown option: --%s", prefix, name)
				}
				return errf("%s%v", prefix, err)
			}
			continue
		}
		if len(arg) >= 2 && arg[0] == '-' {
			// short options; "+" options
			if arg[1] == '+' {
				rest := arg[2:]
				if rest == "" {
					continue
				}
				switch rest {
				case "x":
					o.sort = false
					continue
				case "i":
					o.caseSensitive = -1
					continue
				case "m":
					o.multi = false
					continue
				case "s":
					o.sort = false
					continue
				default:
					return errf("%sunknown option: %s", prefix, arg)
				}
			}
			rest := arg[1:]
			j := 0
			for j < len(rest) {
				c := rest[j]
				j++
				val := ""
				if j < len(rest) {
					val = rest[j:]
				}
				switch c {
				case 'e':
					o.exact = true
				case 'x':
					o.sort = true
				case 'i':
					o.caseSensitive = -1
				case 'n':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -n", prefix)
						}
					}
					o.nth = val
					j = len(rest)
				case 'd':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -d", prefix)
						}
					}
					o.delimiter = val
					j = len(rest)
				case 'm':
					o.multi = true
					if val != "" {
						n, ok := atoi(val)
						if !ok || n <= 0 {
							return errf("%sinvalid multi limit: %s", prefix, val)
						}
						o.multiMax = n
					}
					j = len(rest)
				case 'q':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -q", prefix)
						}
					}
					o.query = val
					j = len(rest)
				case 'f':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -f", prefix)
						}
					}
					o.filter = val
					o.filterMode = true
					j = len(rest)
				case '1':
					o.select1 = true
				case '0':
					o.exit0 = true
				case 's':
					o.sort = false
				case 'h':
					return errHelp
				default:
					return errf("%sunknown option: -%c", prefix, c)
				}
			}
			continue
		}
		return errf("%sunknown option: %s", prefix, arg)
	}
	return nil
}

var errUnknownOption = &optErr{msg: "\x00unknown\x00"}
var errHelp = &optErr{msg: "\x00help\x00"}

func expectValue(name string, hasValue bool, value string, args []string, i *int) (string, bool, error) {
	if hasValue {
		return value, true, nil
	}
	if *i < len(args) {
		v := args[*i]
		*i++
		return v, true, nil
	}
	return "", false, nil
}

func handleOption(o *Options, name string, hasValue bool, value string, args []string, i *int) error {
	get := func() (string, bool, error) {
		if hasValue {
			return value, true, nil
		}
		if *i < len(args) {
			v := args[*i]
			*i++
			return v, true, nil
		}
		return "", false, nil
	}
	need := func() (string, error) {
		v, ok, err := get()
		if err != nil {
			return "", err
		}
		if !ok {
			return "", errf("unexpected value for --%s", name)
		}
		return v, nil
	}
	optional := func() (string, bool, error) {
		if hasValue {
			return value, true, nil
		}
		if *i < len(args) {
			v := args[*i]
			if !strings.HasPrefix(v, "-") || len(v) > 1 && (v[1] >= '0' && v[1] <= '9') {
				*i++
				return v, true, nil
			}
		}
		return "", false, nil
	}

	switch name {
	case "help":
		return errHelp
	case "version":
		if hasValue {
			return errf("unexpected value for --version: %s", value)
		}
		return errVersion
	case "man":
		return errMan
	case "bash":
		return errBash
	case "zsh":
		return errZsh
	case "fish":
		return errFish

	// search
	case "exact":
		o.exact = true
	case "extended":
		o.sort = true
	case "ignore-case":
		o.caseSensitive = -1
	case "no-ignore-case", "case-sensitive":
		o.caseSensitive = 1
	case "smart-case":
		o.caseSensitive = 0
	case "scheme":
		v, err := need()
		if err != nil {
			return err
		}
		switch v {
		case "default":
			o.scheme = schemeDefault
		case "path":
			o.scheme = schemePath
		case "history":
			o.scheme = schemeHistory
		default:
			return errf("invalid scoring scheme (expected: default / path / history)")
		}
		o.schemeName = v
	case "algo":
		v, err := need()
		if err != nil {
			return err
		}
		if v != "v1" && v != "v2" {
			return errf("invalid algorithm (expected: v1 or v2)")
		}
		o.algo = v
	case "nth":
		v, err := need()
		if err != nil {
			return err
		}
		o.nth = v
	case "with-nth":
		v, err := need()
		if err != nil {
			return err
		}
		o.withNth = v
	case "accept-nth":
		v, err := need()
		if err != nil {
			return err
		}
		o.acceptNth = v
	case "delimiter":
		v, err := need()
		if err != nil {
			return err
		}
		o.delimiter = v
	case "sort":
		o.sort = true
	case "literal":
		o.literal = true
	case "tail":
		v, err := need()
		if err != nil {
			return err
		}
		n, ok := atoi(v)
		if !ok || n < 0 {
			return errf("invalid argument: %s", v)
		}
		o.tail = n
	case "disabled":
		o.disabled = true
	case "tiebreak":
		v, err := need()
		if err != nil {
			return err
		}
		if _, err := parseCriteria(v); err != nil {
			return err
		}
		o.tiebreak = v

	// input/output
	case "read0":
		o.read0 = true
	case "print0":
		o.print0 = true
	case "ansi":
		o.ansi = true
	case "sync":
		o.sync = true
	case "tty-default":
		v, err := need()
		if err != nil {
			return err
		}
		o.ttyDefault = v
	case "no-tty-default":
		o.ttyDefault = "stderr"

	// style
	case "style":
		v, err := need()
		if err != nil {
			return err
		}
		base := v
		if idx := strings.Index(v, ":"); idx >= 0 {
			base = v[:idx]
		}
		switch base {
		case "default", "minimal", "full":
		default:
			return errf("invalid style preset (expected: default / minimal / full)")
		}
		o.style = v
	case "color":
		v, err := need()
		if err != nil {
			return err
		}
		o.colorSpecs = append(o.colorSpecs, v)
	case "black":
		o.black = true

	// display mode
	case "height":
		v, err := need()
		if err != nil {
			return err
		}
		o.height = v
	case "min-height":
		v, err := need()
		if err != nil {
			return err
		}
		o.minHeight = v
	case "tmux":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			o.tmux = v
		} else {
			o.tmux = "center,50%"
		}

	// layout
	case "layout":
		v, err := need()
		if err != nil {
			return err
		}
		switch v {
		case "default", "reverse", "reverse-list":
			o.layout = v
		default:
			return errf("invalid layout (expected: default / reverse / reverse-list)")
		}
	case "reverse":
		o.layout = "reverse"
	case "margin":
		v, err := need()
		if err != nil {
			return err
		}
		o.margin = v
	case "padding":
		v, err := need()
		if err != nil {
			return err
		}
		o.padding = v
	case "border":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			if _, err := parseBorderStyle(v); err != nil {
				return err
			}
			o.border = v
		} else {
			o.border = "rounded"
		}
	case "border-label":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			o.borderLabel = v
		}
	case "border-label-pos":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			o.borderLabelPos = v
		}
	case "list-border":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			if _, err := parseBorderStyle(v); err != nil {
				return err
			}
			o.listBorder = v
		} else {
			o.listBorder = "rounded"
		}
	case "list-label":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			o.listLabel = v
		}
	case "list-label-pos":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			o.listLabelPos = v
		}

	// list section
	case "multi":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		o.multi = true
		if ok {
			n, e := atoi(v)
			if !e {
				return errf("invalid argument: %s", v)
			}
			o.multiMax = n
		}
	case "highlight-line":
		o.highlightLine = true
	case "cycle":
		o.cycle = true
	case "wrap":
		o.wrap = true
	case "wrap-sign":
		v, err := need()
		if err != nil {
			return err
		}
		o.wrapSign = v
	case "raw":
		o.raw = true
	case "track":
		o.track = true
	case "tac":
		o.tac = true
	case "gap":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		o.gapGiven = true
		o.gap = 1
		if ok {
			n, e := atoi(v)
			if !e || n < 0 {
				return errf("invalid argument: %s", v)
			}
			o.gap = n
		}
	case "gap-line":
		v, ok, err := optional()
		if err != nil {
			return err
		}
		if ok {
			o.gapLine = v
		} else {
			o.gapLine = "\x00default"
		}
	case "freeze-left":
		v, err := need()
		if err != nil {
			return err
		}
		n, ok := atoi(v)
		if !ok || n < 0 {
			return errf("invalid argument: %s", v)
		}
		o.freezeLeft = n
	case "freeze-right":
		v, err := need()
		if err != nil {
			return err
		}
		n, ok := atoi(v)
		if !ok || n < 0 {
			return errf("invalid argument: %s", v)
		}
		o.freezeRight = n
	case "keep-right":
		o.keepRight = true
	case "scroll-off":
		v, err := need()
		if err != nil {
			return err
		}
		n, ok := atoi(v)
		if !ok || n < 0 {
			return errf("invalid argument: %s", v)
		}
		o.scrollOff = n
	case "hscroll-off":
		v, err := need()
		if err != nil {
