// ParseOptions parses the given arguments into the options struct.
// src is used to prefix error messages ("$FZF_DEFAULT_OPTS", "" for the
// command line).
func ParseOptions(o *Options, args []string, src string) error {
	o.src = src
	prefix := ""
	if src != "" {
		prefix = src + ": "
	}
	i := 0
	for i < len(args) {
		arg := args[i]
		i++
		if arg == "--" {
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			// negation
			if strings.HasPrefix(name, "no-") {
				base := name[3:]
				if err := handleNegation(o, base, hasValue, value); err != nil {
					return errf("%s%v", prefix, err)
				}
				continue
			}
			if err := handleOption(o, name, hasValue, value, args, &i); err != nil {
				if err == errUnknownOption {
					return errf("%sunknown option: --%s", prefix, name)
				}
				return errf("%s%v", prefix, err)
			}
			continue
		}
		if len(arg) >= 2 && arg[0] == '-' {
			// short options; "+" options
			if arg[1] == '+' {
				rest := arg[2:]
				if rest == "" {
					continue
				}
				switch rest {
				case "x":
					o.sort = false
					continue
				case "i":
					o.caseSensitive = -1
					continue
				case "m":
					o.multi = false
					continue
				case "s":
					o.sort = false
					continue
				default:
					return errf("%sunknown option: %s", prefix, arg)
				}
			}
			rest := arg[1:]
			j := 0
			for j < len(rest) {
				c := rest[j]
				j++
				val := ""
				if j < len(rest) {
					val = rest[j:]
				}
				switch c {
				case 'e':
					o.exact = true
				case 'x':
					o.sort = true
				case 'i':
					o.caseSensitive = -1
				case 'n':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -n", prefix)
						}
					}
					o.nth = val
					j = len(rest)
				case 'd':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -d", prefix)
						}
					}
					o.delimiter = val
					j = len(rest)
				case 'm':
					o.multi = true
					if val != "" {
						n, ok := atoi(val)
						if !ok || n <= 0 {
							return errf("%sinvalid multi limit: %s", prefix, val)
						}
						o.multiMax = n
					}
					j = len(rest)
				case 'q':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -q", prefix)
						}
					}
					o.query = val
					j = len(rest)
				case 'f':
					if val == "" {
						if i < len(args) {
							val = args[i]
							i++
						} else {
							return errf("%sunexpected value for -f", prefix)
						}
					}
					o.filter = val
					o.filterMode = true
					j = len(rest)
				case '1':
					o.select1 = true
				case '0':
					o.exit0 = true
				case 's':
					o.sort = false
				case 'h':
					return errHelp
				default:
					return errf("%sunknown option: -%c", prefix, c)
				}
			}
			continue
		}
		return errf("%sunknown option: %s", prefix, arg)
	}
	return nil
}

