			return v, true, nil
		}
		return "", false, nil
	}
	need := func() (string, error) {
		v, ok, err := get()
		if err != nil {
			return "", err
		}
		if !ok {
			return "", errf("unexpected value for --%s", name)
		}
		return v, nil
	}
	optional := func() (string, bool, error) {
		if hasValue {
			return value, true, nil
		}
		if *i < len(args) {
			v := args[*i]
			if !strings.HasPrefix(v, "-") || len(v) > 1 && (v[1] >= '0' && v[1] <= '9') {
				*i++
				return v, true, nil
			}
		}
		return "", false, nil
	}

	switch name {
	case "help":
		return errHelp
	case "version":
		if hasValue {
			return errf("unexpected value for --version: %s", value)
		}
		return errVersion
	case "man":
