}

func runMan() int {
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}
	cmd := exec.Command(shell, "-c", "man fzf")
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()
	return 0
}

func splitWords(s string) []string {
	var out []string
	var cur strings.Builder
	inQuote := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inQuote != 0:
			if c == inQuote {
				inQuote = 0
			} else {
				cur.WriteByte(c)
			}
		case c == '"' || c == '\'':
			inQuote = c
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			if cur.Len() > 0 {
				out = append(out, cur.String())
				cur.Reset()
			}
		default:
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		out = append(out, cur.String())
	}
	return out
}

// ---------------------------------------------------------------------------
// Filter mode
// ---------------------------------------------------------------------------

func runFilter(o *Options) int {
	items, err := readItems(o)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		return 2
	}
	query := o.filter
	if o.query != "" && o.filter == "" {
		query = o.query
	}
	pat := buildPattern(query, o.exact, caseSensitiveOf(o), !o.literal, o.scheme)

	criteria, err := parseCriteria(o.tiebreak)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		return 2
	}

	out := os.Stdout
	if o.printQuery {
		if o.print0 {
			fmt.Fprintf(out, "%s\x00", query)
		} else {
			fmt.Fprintf(out, "%s\n", query)
		}
	}
	results := make([]*result, 0, len(items))
	for _, it := range items {
		text := it.searchText()
		if len(pat.termSets) == 0 {
			results = append(results, &result{item: it, res: Result{0, 0, 0}})
			continue
		}
		res, pos, ok := matchPattern(pat, text)
		if !ok {
			continue
		}
		results = append(results, &result{item: it, res: res, pos: pos})
	}
	sortResults(results, criteria, !o.sort)
	sep := "\n"
	if o.print0 {
		sep = "\x00"
	}
	for _, r := range results {
		fmt.Fprint(out, r.item.displayText())
		fmt.Fprint(out, sep)
	}
	return 0
}

func caseSensitiveOf(o *Options) bool {
	switch o.caseSensitive {
	case 1:
		return true
	case -1:
		return false
	}
	// smart case
	for _, r := range o.query + o.filter {
		if r >= 'A' && r <= 'Z' {
			return true
		}
	}
	return false
}

