// ---------------------------------------------------------------------------
// Reading input
// ---------------------------------------------------------------------------

type itemReader struct {
	opts *Options
	split *splitter
	nth   []fieldRange
	withNth []fieldRange
	withTemplate string
}

func readItems(o *Options) ([]*Item, error) {
	sp, err := newSplitter(o.delimiter)
	if err != nil {
		return nil, errf("invalid delimiter regexp: %s", o.delimiter)
	}
	var nth, withNth []fieldRange
	if o.nth != "" {
		nth, err = parseFieldRange(o.nth)
		if err != nil {
			return nil, err
		}
	}
	if o.withNth != "" {
		withNth, err = parseFieldRange(o.withNth)
		if err != nil {
			return nil, err
		}
	}
	var data []byte
	if isTTY(os.Stdin) {
		// run FZF_DEFAULT_COMMAND or the built-in walker
		cmd := os.Getenv("FZF_DEFAULT_COMMAND")
		if cmd == "" {
			// built-in directory walker
			items, err := walkDir(o)
			if err != nil {
				return nil, err
			}
			return finalizeItems(o, items, sp, nth, withNth)
		}
		shell := os.Getenv("SHELL")
		if shell == "" {
			shell = "sh"
		}
		c := exec.Command(shell, "-c", cmd)
		out, err := c.Output()
		if err != nil {
			return nil, err
		}
		data = out
	} else {
		data, err = io.ReadAll(os.Stdin)
		if err != nil {
			return nil, err
		}
	}
	lines := splitLines(string(data), o.read0)
	return finalizeItems(o, lines, sp, nth, withNth)
}

func finalizeItems(o *Options, lines []string, sp *splitter, nth, withNth []fieldRange) ([]*Item, error) {
	if o.headerLines > 0 {
		if len(lines) >= o.headerLines {
			lines = lines[o.headerLines:]
		} else {
			lines = nil
		}
	}
	if o.tac {
		// reverse
		for i, j := 0, len(lines)-1; i < j; i, j = i+1, j-1 {
			lines[i], lines[j] = lines[j], lines[i]
		}
	}
	items := make([]*Item, 0, len(lines))
	for idx, line := range lines {
		it := newItem(line, idx, o, sp, nth, withNth)
		items = append(items, it)
	}
	return items, nil
}

func newItem(line string, idx int, o *Options, sp *splitter, nth, withNth []fieldRange) *Item {
	it := &Item{orig: line, index: int32(idx)}
	if o.ansi {
		it.ansi = true
		it.plain = stripAnsi(line)
	} else {
		it.plain = line
	}
	it.splitter = sp
	if len(withNth) > 0 {
		fields := sp.split(it.plain)
		it.transformedStr = joinFields(fields, withNth, sp)
	}
	return it
}

func joinFields(fields []string, ranges []fieldRange, sp *splitter) string {
	var sb strings.Builder
	first := true
	for _, fr := range ranges {
		for i := range fields {
			if !fieldMatches(i+1, len(fields), fr) {
				continue
			}
			if !first {
				if sp.isAwkStyle {
					sb.WriteByte(' ')
				} else {
					sb.WriteString(sp.delimSep())
				}
			}
			sb.WriteString(fields[i])
			first = false
		}
	}
	return sb.String()
}

func fieldMatches(n, total int, fr fieldRange) bool {
	b, e := fr.begin, fr.end
	if b < 0 {
		b = total + b + 1
	}
	if e < 0 {
		e = total + e + 1
	}
	if e == -1 {
		e = total
	}
	if b < 1 {
		b = 1
	}
	if e > total {
		e = total
	}
	return n >= b && n <= e
}

func (s *splitter) delimSep() string {
	return " "
}

func splitLines(s string, read0 bool) []string {
	sep := byte('\n')
	if read0 {
		sep = 0
	}
	var lines []string
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] == sep {
			lines = append(lines, s[start:i])
			start = i + 1
		}
	}
	if start < len(s) {
		lines = append(lines, s[start:])
	}
	// trailing empty line is not an item
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	return lines
}

func isTTY(f *os.File) bool {
	st, err := f.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice != 0
}

// searchText returns the runes to match against
func (i *Item) searchText() []rune {
	if i.transformedStr != "" {
		return []rune(i.transformedStr)
	}
	return []rune(i.plain)
}

func (i *Item) displayText() string {
	if i.transformedStr != "" {
		return i.transformedStr
	}
	return i.orig
}

