// ---------------------------------------------------------------------------
// Built-in directory walker
// ---------------------------------------------------------------------------

func walkDir(o *Options) ([]string, error) {
	root := "."
	if len(o.walkerRoot) > 0 {
		root = o.walkerRoot[0]
	}
	includeFile, includeDir, follow, hidden := true, false, true, true
	if o.walker != "" {
		includeFile, includeDir, follow, hidden = false, false, false, false
		for _, part := range strings.Split(o.walker, ",") {
			switch part {
			case "file":
				includeFile = true
			case "dir":
				includeDir = true
			case "follow":
				follow = true
			case "hidden":
				hidden = true
			}
		}
	}
	skip := map[string]bool{}
	if o.walkerSkip != "" {
		for _, d := range strings.Split(o.walkerSkip, ",") {
			skip[d] = true
		}
	} else {
		skip[".git"] = true
		skip["node_modules"] = true
	}
	var out []string
	var walk func(dir string, isRoot bool)
	walk = func(dir string, isRoot bool) {
		entries, err := os.ReadDir(dir)
		if err != nil {
			return
		}
		sortDirs(entries)
		for _, e := range entries {
			name := e.Name()
			if name == "." || name == ".." {
				continue
			}
			path := name
			if !isRoot {
				path = dir + "/" + name
			} else if dir != "." {
				path = dir + "/" + name
			}
			if e.IsDir() {
				if skip[name] {
					continue
				}
				if strings.HasPrefix(name, ".") && !hidden && !isRoot {
					continue
				}
				if includeDir {
					out = append(out, path+"/")
				}
				walk(path, false)
				continue
			}
			if !includeFile {
				continue
			}
			if strings.HasPrefix(name, ".") && !hidden {
				continue
			}
			out = append(out, path)
		}
	}
	walk(root, true)
	return out, nil
}

func sortDirs(entries []os.DirEntry) {
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
}
