{"command": "cd /tmp/work && cat > tui.go <<'GOEOF'
package main

import (
	"os"
	"strings"
	"syscall"
	"unsafe"
)

// ---------------------------------------------------------------------------
// Terminal handling
// ---------------------------------------------------------------------------

const (
	ioctlGetTermios = 0x5401
	ioctlSetTermios = 0x5402
	ioctlGetWinsize = 0x5413
)

type winsize struct {
	Row, Col, X, Y uint16
}

func getWinsize(fd uintptr) (int, int) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, ioctlGetWinsize, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

type terminal struct {
	in      *os.File
	out     *os.File
	orig    syscall.Termios
	raw     bool
	cols    int
	rows    int
	fd      uintptr
	alt     bool
	savedX  int
	savedY  int
}

func newTerminal() (*terminal, error) {
	var t terminal
	dev := "/dev/tty"
	if v := os.Getenv("FZF_TTY_DEFAULT"); v != "" {
		dev = v
	}
	f, err := os.OpenFile(dev, os.O_RDWR, 0)
	if err != nil {
		return nil, errTTY
	}
	t.in = f
	t.out = os.Stdout
	t.fd = f.Fd()
	t.cols, t.rows = getWinsize(t.fd)
	return &t, nil
}

var errTTY = &ttyErr{}

type ttyErr struct{}

func (e *ttyErr) Error() string { return "failed to open /dev/tty" }

func (t *terminal) enterRaw() {
	var tio syscall.Termios
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, t.fd, ioctlGetTermios, uintptr(unsafe.Pointer(&tio))); errno != 0 {
		return
	}
	t.orig = tio
	raw := tio
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	syscall.Syscall(syscall.SYS_IOCTL, t.fd, ioctlSetTermios, uintptr(unsafe.Pointer(&raw)))
	t.raw = true
}

func (t *terminal) restore() {
	if t.raw {
		syscall.Syscall(syscall.SYS_IOCTL, t.fd, ioctlSetTermios, uintptr(unsafe.Pointer(&t.orig)))
		t.raw = false
	}
}

func (t *terminal) resize() {
	t.cols, t.rows = getWinsize(t.fd)
}

func (t *terminal) write(s string) {
	os.Stdout.WriteString(s)
}

// ---------------------------------------------------------------------------
// Key parsing
// ---------------------------------------------------------------------------

type key struct {
	name string
	chr  rune
}

var ctrlKeys = map[byte]string{
	0:  "ctrl-space",
	1:  "ctrl-a", 2: "ctrl-b", 3: "ctrl-c", 4: "ctrl-d", 5: "ctrl-e", 6: "ctrl-f",
	7: "ctrl-g", 8: "ctrl-h", 9: "tab", 10: "enter", 11: "ctrl-k", 12: "ctrl-l",
	13: "enter", 14: "ctrl-n", 15: "ctrl-o", 16: "ctrl-p", 17: "ctrl-q", 18: "ctrl-r",
	19: "ctrl-s", 20: "ctrl-t", 21: "ctrl-u", 22: "ctrl-v", 23: "ctrl-w", 24: "ctrl-x",
	25: "ctrl-y", 26: "ctrl-z", 27: "esc", 28: "ctrl-\\", 29: "ctrl-]", 30: "ctrl-^", 31: "ctrl-/",
	127: "bspace",
}

// parseKeys parses a buffer of input bytes into keys.
func parseKeys(buf []byte) ([]key, []byte) {
	var keys []key
	i := 0
	for i < len(buf) {
		b := buf[i]
		if b == 0x1b {
			// escape sequence
			if i+1 >= len(buf) {
				keys = append(keys, key{name: "esc"})
				i++
				continue
			}
			switch buf[i+1] {
			case '[':
				// CSI
				j := i + 2
				for j < len(buf) && !(buf[j] >= 0x40 && buf[j] <= 0x7e) {
					j++
				}
				if j >= len(buf) {
					return keys, buf[i:]
				}
				seq := string(buf[i+2 : j])
				final := string(buf[j])
				keys = append(keys, key{name: csiName(seq, final)})
				i = j + 1
				continue
			case 'O':
				if i+2 < len(buf) {
					keys = append(keys, key{name: ss3Name(buf[i+2])})
					i += 3
					continue
				}
				return keys, buf[i:]
			case 0x1b:
				keys = append(keys, key{name: "esc"})
				i++
				continue
			default:
				// alt-key
				r, size := decodeRune(buf[i+1:])
				if size == 0 {
					return keys, buf[i:]
				}
				name := "alt-" + keyNameForRune(r)
				keys = append(keys, key{name: name})
				i += 1 + size
				continue
			}
		}
		if b < 32 || b == 127 {
			if n, ok := ctrlKeys[b]; ok {
				keys = append(keys, key{name: n})
			} else {
				keys = append(keys, key{name: "ctrl-?"})
			}
			i++
			continue
		}
		r, size := decodeRune(buf[i:])
		if size == 0 {
			return keys, buf[i:]
		}
		if r == '\r' {
			keys = append(keys, key{name: "enter"})
		} else if r == '\n' {
			keys = append(keys, key{name: "enter"})
		} else {
			keys = append(keys, key{chr: r})
		}
		i += size
	}
	return keys, nil
}

func decodeRune(b []byte) (rune, int) {
	if len(b) == 0 {
		return 0, 0
	}
	c := b[0]
	switch {
	case c < 0x80:
		return rune(c), 1
	case c&0xe0 == 0xc0:
		if len(b) < 2 {
			return 0, 0
		}
		return rune(c&0x1f)<<6 | rune(b[1]&0x3f), 2
	case c&0xf0 == 0xe0:
		if len(b) < 3 {
