	jumpTargets map[rune]int
	infoHidden bool
	rawMode  bool
	tall     int
	spinnerRunes []rune
}

var spinnerChars = []rune{'|', '/', '-', '\\'}

func runFinder(o *Options) int {
	t, err := newTerminal()
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		return 2
	}
	f := &finder{
		opts:     o,
		term:     t,
		selected: map[int32]bool{},
		query:    []rune(o.query),
		qpos:     len([]rune(o.query)),
		rawMode:  o.raw,
		criteria: defaultCriteria(o),
	}
	f.delims, _ = newSplitter(o.delimiter)
	if o.header != "" {
		f.header = strings.Split(o.header, "\n")
	}
	if o.footer != "" {
		f.footer = strings.Split(o.footer, "\n")
	}
	for _, exp := range strings.Split(o.expect, ",") {
		if exp = strings.TrimSpace(exp); exp != "" {
			f.expect = append(f.expect, exp)
		}
	}
	t.enterRaw()
	defer t.restore()

	f.height, f.heightPct, f.adaptive = parseHeight(o.height, t.rows, t.cols)

	// Alternate screen for fullscreen mode
	if !o.heightSpecified() {
		t.write("\x1b[?1049h\x1b[H")
	}
	t.write("\x1b[2J")

	// initial read (synchronous)
	f.reloadItems()
	f.readingDone = true

	code := f.loop()

	if !o.heightSpecified() && !o.noClear {
		t.write("\x1b[?1049l")
	}
	t.restore()
	return code
}

func defaultCriteria(o *Options) []criterion {
	c, err := parseCriteria(o.tiebreak)
	if err != nil {
		c = []criterion{critLength, critIndex}
	}
	return c
}

func (o *Options) heightSpecified() bool { return o.height != "" }

func parseHeight(spec string, rows, cols int) (int, bool, bool) {
	if spec == "" {
		return 0, false, false
	}
	adaptive := false
	s := spec
	if strings.HasPrefix(s, "~") {
		adaptive = true
		s = s[1:]
	}
	pct := false
	if strings.HasSuffix(s, "%") {
		pct = true
		s = s[:len(s)-1]
	}
	n, ok := atoi(s)
	if !ok {
		return 0, false, false
	}
	if pct {
		h := rows * n / 100
		if h < 1 {
			h = 1
		}
		return h, true, adaptive
	}
	if n < 0 {
		h := rows + n
		if h < 1 {
			h = 1
		}
		return h, false, adaptive
	}
	if n > rows {
		n = rows
	}
	return n, false, adaptive
}

// reloadItems reads all items from stdin (blocking).
func (f *finder) reloadItems() {
	items, err := readItems(f.opts)
	if err != nil {
		return
	}
	f.items = items
	f.applyPattern()
}

func (f *finder) applyPattern() {
	pat := buildPattern(string(f.query), f.opts.exact, caseSensitiveOf(f.opts), !f.opts.literal, f.opts.scheme)
	f.pattern = pat
	results := make([]*result, 0, len(f.items))
	for _, it := range f.items {
		if len(pat.termSets) == 0 {
			results = append(results, &result{item: it, res: Result{0, 0, 0}})
			continue
		}
		res, pos, ok := matchPattern(pat, it.searchText())
		if !ok {
			continue
		}
		results = append(results, &result{item: it, res: res, pos: pos})
	}
	sortResults(results, f.criteria, !f.opts.sort)
	f.results = results
	if f.cursor >= len(results) {
		f.cursor = len(results) - 1
	}
	if f.cursor < 0 {
		f.cursor = 0
	}
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

func (f *finder) loop() int {
	// set up input reading
	inputCh := make(chan []byte, 64)
	go func() {
		buf := make([]byte, 4096)
		for {
			n, err := f.term.in.Read(buf)
			if n > 0 {
				b := make([]byte, n)
				copy(b, buf[:n])
				inputCh <- b
			}
			if err != nil {
				close(inputCh)
				return
			}
		}
	}()

	// select-1 / exit-0
	if f.opts.exit0 && len(f.results) == 0 {
		return f.finish(1)
	}
	if f.opts.select1 && len(f.results) == 1 {
		return f.accept()
	}

	f.render()
	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	pending := []byte{}
	for !f.done {
		select {
		case b, ok := <-inputCh:
			if !ok {
				return f.finish(130)
			}
			pending = append(pending, b...)
			keys, rest := parseKeys(pending)
			pending = rest
			for _, k := range keys {
				if f.handleKey(k) {
					break
				}
			}
			if f.done {
				return f.finish(f.exitCode)
			}
			f.render()
		case <-ticker.C:
			f.spinner = (f.spinner + 1) % len(spinnerChars)
			f.render()
		}
	}
	return f.finish(f.exitCode)
}

func (f *finder) finish(code int) int {
	if f.expectKey != "" {
		// print the key name
		if f.opts.printQuery {
			if f.opts.print0 {
				fmt.Print(f.queryString(), "\x00")
			} else {
				fmt.Println(f.queryString())
			}
		}
		if f.opts.print0 {
			fmt.Print(f.expectKey, "\x00")
		} else {
			fmt.Println(f.expectKey)
		}
		f.printSelected()
		return 0
	}
	if f.opts.printQuery {
		if f.opts.print0 {
			fmt.Print(f.queryString(), "\x00")
		} else {
			fmt.Println(f.queryString())
		}
	}
	f.printSelected()
	return code
}

func (f *finder) queryString() string { return string(f.query) }

func (f *finder) printSelected() {
	if len(f.selected) == 0 {
		if f.cursor >= 0 && f.cursor < len(f.results) {
			f.printItem(f.results[f.cursor].item)
		}
		return
	}
	// print in the input order
	var sel []*Item
	for _, r := range f.results {
		if f.selected[r.item.index] {
			sel = append(sel, r.item)
		}
	}
	for _, it := range sel {
		f.printItem(it)
	}
}

func (f *finder) printItem(it *Item) {
	if f.opts.print0 {
		fmt.Print(it.displayText(), "\x00")
	} else {
		fmt.Println(it.displayText())
	}
}

func (f *finder) accept() int {
	if len(f.results) == 0 && f.opts.acceptNonEmpty() {
		return 0
	}
	f.done = true
	if len(f.results) == 0 {
		f.exitCode = 1
	}
	return f.exitCode
}

func (o *Options) acceptNonEmpty() bool { return false }

// layout returns the vertical layout: a list of section heights
func (f *finder) layout() (listH, infoH, promptH, headerH, footerH, borderT, borderB int) {
	o := f.opts
	H := f.height
	if !o.heightSpecified() {
		H = f.term.rows
	}
	// subtract margins
	// sections
	infoH = 1
	if o.info == "hidden" {
		infoH = 0
	}
	if o.info != "" && strings.HasPrefix(o.info, "inline") {
		infoH = 0
	}
	promptH = 1
	if o.noInput {
		promptH = 0
	}
	headerH = len(f.header)
	footerH = len(f.footer)
	borderT, borderB = 0, 0
	if o.border != "" && o.border != "none" {
		if o.border == "line" {
			borderT = 1
		} else {
			borderT, borderB = 1, 1
		}
	}
	listH = H - borderT - borderB - headerH - footerH - infoH - promptH
	if listH < 1 {
		listH = 1
	}
	return
}

func (f *finder) render() {
	o := f.opts
	cols, rows := f.term.cols, f.term.rows
	W := cols
	H := rows
	if o.heightSpecified() {
		H = f.height
	}
	var b strings.Builder
	reverse := o.layout == "reverse" || o.layout == "reverse-list"
	infoInline := strings.HasPrefix(o.info, "inline")
	infoHidden := o.info == "hidden"

	// compute rows
	headerRows := len(f.header)
	footerRows := len(f.footer)
	infoRows := 0
	if !infoInline && !infoHidden {
		infoRows = 1
	}
	promptRows := 1
	if o.noInput {
		promptRows = 0
	}
	listRows := H - headerRows - footerRows - infoRows - promptRows
	if listRows < 1 {
		listRows = 1
	}

	y := 0
	var headerLines []string
	var listLines []string
	var infoLine string
	var promptLine string
	var footerLines []string

	// build list lines
	listLines = f.renderList(listRows)

	if !infoHidden {
		infoLine = f.renderInfo(W)
	}
	promptLine = f.renderPrompt(W)
	headerLines = f.header
	footerLines = f.footer

	// order
	var order []([]string)
	if reverse {
		order = append(order, headerLines, listLines)
		if !infoInline && !infoHidden {
			order = append(order, []string{infoLine})
		}
		if promptRows > 0 {
			order = append(order, []string{promptLine})
		}
		if footerRows > 0 {
			order = append(order, footerLines)
		}
	} else {
		if headerRows > 0 {
			order = append(order, headerLines)
		}
		if footerRows > 0 {
			order = append(order, footerLines)
		}
		order = append(order, listLines)
		if !infoInline && !infoHidden {
			order = append(order, []string{infoLine})
		}
		if promptRows > 0 {
			order = append(order, []lineRender{{s: promptLine}})
		}
	}
	b.WriteString("\x1b[H")
	for _, sec := range order {
		for _, l := range sec {
			b.WriteString("\x1b[2K")
			b.WriteString(l.s)
			b.WriteString("\r\n")
			y++
		}
	}
	f.term.write(b.String())
}
