// ---------------------------------------------------------------------------
// Color palette
// ---------------------------------------------------------------------------

type colAttr struct {
	fg    int
	bg    int
	bold  bool
	dim   bool
	under bool
	rev   bool
	ital  bool
	strike bool
	regular bool
}

type palette struct {
