func ansiFor(a colAttr, boldOff bool) string {
	var b strings.Builder
	b.WriteString("\x1b[0m")
	if a.regular {
		// nothing else
		return b.String()
	}
	if a.fg >= 0 {
		if a.fg < 8 {
			fmt.Fprintf(&b, "\x1b[%dm", 30+a.fg)
		} else if a.fg < 16 {
			fmt.Fprintf(&b, "\x1b[%dm", 90+a.fg-8)
		} else {
			fmt.Fprintf(&b, "\x1b[38;5;%dm", a.fg)
		}
	} else {
		b.WriteString("\x1b[39m")
	}
	if a.bg >= 0 {
		if a.bg < 8 {
			fmt.Fprintf(&b, "\x1b[%dm", 40+a.bg)
		} else if a.bg < 16 {
			fmt.Fprintf(&b, "\x1b[%dm", 100+a.bg-8)
		} else {
			fmt.Fprintf(&b, "\x1b[48;5;%dm", a.bg)
		}
	} else {
		b.WriteString("\x1b[49m")
	}
	if a.bold && !boldOff {
		b.WriteString("\x1b[1m")
	}
	if a.dim {
		b.WriteString("\x1b[2m")
	}
	if a.under {
		b.WriteString("\x1b[4m")
	}
	if a.rev {
		b.WriteString("\x1b[7m")
	}
	if a.ital {
