func ansiFor(a colAttr, boldOff bool) string {
	var b strings.Builder
	b.WriteString("\x1b[0m")
	if a.regular {
		// nothing else
		return b.String()
	}
	if a.fg >= 0 {
		if a.fg < 8 {
			fmt.Fprintf(&b, "\x1b[%dm", 30+a.fg)
		} else if a.fg < 16 {
			fmt.Fprintf(&b, "\x1b[%dm", 90+a.fg-8)
		} else {
			fmt.Fprintf(&b, "\x1b[38;5;%dm", a.fg)
		}
	} else {
		b.WriteString("\x1b[39m")
	}
	if a.bg >= 0 {
		if a.bg < 8 {
			fmt.Fprintf(&b, "\x1b[%dm", 40+a.bg)
		} else if a.bg < 16 {
			fmt.Fprintf(&b, "\x1b[%dm", 100+a.bg-8)
		} else {
			fmt.Fprintf(&b, "\x1b[48;5;%dm", a.bg)
		}
	} else {
		b.WriteString("\x1b[49m")
	}
	if a.bold && !boldOff {
		b.WriteString("\x1b[1m")
	}
	if a.dim {
		b.WriteString("\x1b[2m")
	}
	if a.under {
		b.WriteString("\x1b[4m")
	}
	if a.rev {
		b.WriteString("\x1b[7m")
	}
	if a.ital {
		b.WriteString("\x1b[3m")
	}
	if a.strike {
		b.WriteString("\x1b[9m")
	}
	return b.String()
}

func base16Palette() *palette {
	p := &palette{profile: 0, unicode: true, c: map[string]colAttr{}}
	set := func(n string, fg, bg int, bold, dim bool) { p.c[n] = colAttr{fg: fg, bg: bg, bold: bold, dim: dim} }
	set("fg", -1, -1, false, false)
	set("fg+", 15, 8, true, false)
	set("hl", 2, -1, false, false)
	set("hl+", 10, 8, true, false)
	set("fg-prev", -1, -1, true, false)
	set("gutter", 8, -1, false, false)
	set("gutter-raw", 8, -1, false, false)
	set("pointer", 1, 8, true, false)
	set("marker", 5, 8, true, false)
	set("query", 4, -1, false, false)
	set("prompt", 4, -1, true, false)
	set("info", 3, -1, false, false)
	set("separator", -1, -1, false, true)
	set("scrollbar", -1, -1, false, true)
	set("border", -1, -1, false, true)
	set("border-label", -1, -1, false, true)
	set("header", 2, -1, false, false)
	set("footer", -1, -1, false, false)
	set("spinner", 3, -1, false, false)
	set("preview-fg", -1, -1, false, false)
	set("preview-border", -1, -1, false, true)
	set("input-border", -1, -1, false, true)
	set("header-border", -1, -1, false, true)
	set("list-border", -1, -1, false, true)
	set("selected-fg", -1, -1, false, false)
	set("selected-bg", -1, -1, false, false)
	set("nomatch", -1, -1, false, true)
	set("nth", -1, -1, false, true)
	set("ellipsis", -1, -1, false, true)
	set("bg", -1, -1, false, false)
	set("bg+", -1, 8, false, false)
	set("preview-bg", -1, -1, false, false)
	set("disabled", -1, -1, false, true)
	return p
}

func darkPalette() *palette {
	p := base16Palette()
	p.profile = 1
	c := p.c
	c["fg"] = colAttr{fg: 252, bg: 234, bold: false}
	c["fg+"] = colAttr{fg: 254, bg: 235, bold: true}
	c["hl"] = colAttr{fg: 65, bg: -1, bold: false}
	c["hl+"] = colAttr{fg: 108, bg: 235, bold: true}
	c["bg"] = colAttr{fg: -1, bg: 234}
	c["bg+"] = colAttr{fg: -1, bg: 235}
	c["gutter"] = colAttr{fg: 239, bg: -1}
	c["pointer"] = colAttr{fg: 161, bg: 235, bold: true}
	c["marker"] = colAttr{fg: 168, bg: 235, bold: true}
	c["info"] = colAttr{fg: 144, bg: -1}
	c["prompt"] = colAttr{fg: 110, bg: -1, bold: true}
	c["query"] = colAttr{fg: 110, bg: -1}
	c["spinner"] = colAttr{fg: 148, bg: -1}
	c["header"] = colAttr{fg: 65, bg: -1}
	c["scrollbar"] = colAttr{fg: 239, bg: -1, dim: true}
	c["separator"] = colAttr{fg: 239, bg: -1, dim: true}
	c["border"] = colAttr{fg: 239, bg: -1, dim: true}
	return p
}

func bwPalette() *palette {
	p := base16Palette()
	p.profile = 2
	for k := range p.c {
		a := p.c[k]
		a.fg = -1
		a.bg = -1
		switch k {
		case "fg+", "hl+", "pointer", "marker", "prompt", "query":
			a.bold = true
		case "hl":
			a.under = true
		case "separator", "scrollbar", "border", "nth", "nomatch", "ellipsis", "gutter", "gutter-raw":
			a.dim = true
		}
		p.c[k] = a
	}
	return p
}

func (p *palette) get(name string) colAttr {
	if a, ok := p.c[name]; ok {
		return a
	}
	return colAttr{fg: -1, bg: -1}
}

// ---------------------------------------------------------------------------
// Finder
// ---------------------------------------------------------------------------

type finder struct {
	opts      *Options
	term      *terminal
	pal       *palette
	items     []*Item
	results   []*result
	cursor    int
	offset    int
	selected  map[int32]bool
	query     []rune
	qpos      int
	header    []string
	headerLn  []string
	footer    []string
	expect    []string
	expectKey string
	criteria  []criterion
	height    int
	done      bool
	exitCode  int
	spinner   int
	reading   bool
	previewCmd string
	previewBuf  []string
	multiLine  bool
	jumpMode   bool
	jumpLabels []rune
	jumpSel    map[rune]int
	binds      map[string][]action
	rawMode   bool
}

func runFinder(o *Options) int {
	t, err := newTerminal()
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		return 2
	}
	unicodeOK := !o.noUnicode
	var pal *palette
	if o.noColor || os.Getenv("NO_COLOR") != "" {
		pal = bwPalette()
	} else if is256Color() {
		pal = darkPalette()
	} else {
		pal = base16Palette()
	}
	pal.unicode = unicodeOK
	f := &finder{
		opts:     o,
		term:     t,
		pal:      pal,
		selected: map[int32]bool{},
		query:    []rune(o.query),
		qpos:     len([]rune(o.query)),
		rawMode:  o.raw,
	}
	f.criteria = defaultCriteria(o)
	if o.header != "" {
		f.header = strings.Split(o.header, "\n")
	}
	if o.footer != "" {
		f.footer = strings.Split(o.footer, "\n")
	}
	for _, exp := range strings.Split(o.expect, ",") {
		if exp = strings.TrimSpace(exp); exp != "" {
			f.expect = append(f.expect, exp)
		}
	}
	f.binds = parseBinds(o.binds)
	t.enterRaw()
	defer t.restore()

	f.height, _, _ = parseHeight(o.height, t.rows, t.cols)
	if !o.heightSpecified() {
		t.write("\x1b[?1049h\x1b[H")
	}
	t.write("\x1b[2J")

	f.reading = true
	f.render()
	go func() {
		items, _ := readItems(o)
		f.items = items
		f.reading = false
		f.applyPattern()
	}()

	code := f.loop()
	if !o.heightSpecified() && !o.noClear {
		t.write("\x1b[?1049l")
	}
	t.restore()
	return code
}

func is256Color() bool {
	term := os.Getenv("TERM")
	return strings.Contains(term, "256color")
}

// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------

func (f *finder) loop() int {
	inputCh := make(chan []byte, 64)
	go func() {
		buf := make([]byte, 4096)
		for {
			n, err := f.term.in.Read(buf)
			if n > 0 {
				b := make([]byte, n)
				copy(b, buf[:n])
				inputCh <- b
			}
			if err != nil {
				close(inputCh)
				return
			}
		}
	}()
	f.applyPattern()
	if f.opts.exit0 && len(f.results) == 0 {
		return f.finish(1)
	}
	if f.opts.select1 && len(f.results) == 1 {
		return f.accept()
	}
	f.render()
	pending := []byte{}
	ticker := time.NewTicker(80 * time.Millisecond)
	defer ticker.Stop()
	for !f.done {
		select {
		case b, ok := <-inputCh:
			if !ok {
				return f.finish(130)
			}
			pending = append(pending, b...)
			keys, rest := parseKeys(pending)
			pending = rest
			for _, k := range keys {
				if f.handleKey(k) {
					break
				}
			}
			if f.done {
				return f.finish(f.exitCode)
			}
			f.render()
		case <-ticker.C:
			f.spinner = (f.spinner + 1) % len(spinnerChars)
			f.render()
		}
	}
	return f.finish(f.exitCode)
}

func (f *finder) finish(code int) int {
	if f.opts.printQuery {
		if f.opts.print0 {
			fmt.Print(string(f.query), "\x00")
		} else {
			fmt.Println(string(f.query))
		}
	}
	if f.expectKey != "" {
		if f.opts.print0 {
			fmt.Print(f.expectKey, "\x00")
		} else {
			fmt.Println(f.expectKey)
		}
	}
	if code == 0 || f.expectKey != "" {
		f.printSelected()
	}
	return code
}

func (f *finder) printSelected() {
	if !f.opts.multi || len(f.selected) == 0 {
		if f.cursor >= 0 && f.cursor < len(f.results) {
			f.printItem(f.results[f.cursor].item)
		}
		return
	}
	for _, r := range f.results {
		if f.selected[r.item.index] {
			f.printItem(r.item)
		}
	}
}

func (f *finder) printItem(it *Item) {
	if f.opts.acceptNth != "" {
		fmt.Println(transformAccept(it, f.opts.acceptNth, f.delims))
		return
	}
	if f.opts.print0 {
		fmt.Print(it.displayText(), "\x00")
	} else {
		fmt.Println(it.displayText())
	}
}

func (f *finder) accept() int {
	f.done = true
	if len(f.results) == 0 {
		f.exitCode = 1
	}
	return f.exitCode
}

func (f *finder) abort() int {
	f.done = true
	f.exitCode = 130
	return f.exitCode
}

// ---------------------------------------------------------------------------
// Pattern
// ---------------------------------------------------------------------------

func (f *finder) applyPattern() {
	pat := buildPattern(string(f.query), f.opts.exact, caseSensitiveOf(f.opts), !f.opts.literal, f.opts.scheme)
	f.results = make([]*result, 0, len(f.items))
	for _, it := range f.items {
		if len(pat.termSets) == 0 {
			f.results = append(f.results, &result{item: it, res: Result{0, 0, 0}})
			continue
		}
		res, pos, ok := matchPattern(pat, it.searchText())
		if !ok {
			continue
		}
		f.results = append(f.results, &result{item: it, res: res, pos: pos})
	}
	sortResults(f.results, f.criteria, !f.opts.sort)
	if f.cursor >= len(f.results) {
		f.cursor = len(f.results) - 1
	}
	if f.cursor < 0 {
		f.cursor = 0
	}
	f.offset = f.cursor
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

var borderChars = map[borderStyle][6]string{
	borderRounded:  {"╭", "─", "╮", "│", "╰", "╯"},
	borderSharp:    {"┌", "─", "┐", "│", "└", "┘"},
	borderBold:     {"┏", "━", "┓", "┃", "┗", "┛"},
	borderDouble:   {"╔", "═", "╗", "║", "╚", "╝"},
	borderBlock:    {"▛", "▀", "▜", "▌", "▙", "▟"},
	borderThinBlock: {"▛", "▀", "▜", "▌", "▙", "▟"},
	borderHorizontal: {"", "─", "", "", "─", ""},
	borderVertical:  {"", "", "", "│", "", ""},
	borderTop:      {"", "─", "", "", "", ""},
	borderBottom:   {"", "", "", "", "─", ""},
	borderLeft:     {"", "", "", "│", "", ""},
	borderRight:    {"", "", "", "│", "", ""},
}

func (f *finder) width() int {
	w := f.term.cols
	if f.opts.heightSpecified() {
		w = f.term.cols
	}
	return w
}

func (f *finder) render() {
	var b strings.Builder
	o := f.opts
	W := f.width()
	H := f.term.rows
	if o.heightSpecified() {
		H = f.height
	}
	reverse := o.layout == "reverse" || o.layout == "reverse-list"
	infoInline := strings.HasPrefix(o.info, "inline")
	infoHidden := o.info == "hidden" || o.info == ""
	_ = infoHidden

	headerRows := len(f.header)
	footerRows := len(f.footer)
	infoRows := 0
	if !infoInline && o.info != "hidden" {
		infoRows = 1
	}
	promptRows := 1
	if o.noInput {
		promptRows = 0
	}
	listRows := H - headerRows - footerRows - infoRows - promptRows
	if listRows < 1 {
		listRows = 1
	}

	b.WriteString("\x1b[H")
	// sections in display order
	type section struct{ lines []string }
	var secs []section
	listLines := f.renderList(listRows, W)
	if reverse {
		if promptRows > 0 {
			secs = append(secs, section{[]string{f.renderPromptLine(W, infoInline)}})
		}
		if infoRows > 0 {
			secs = append(secs, section{[]string{f.renderInfoLine(W)}})
		}
		secs = append(secs, section{listLines})
		if headerRows > 0 {
			secs = append(secs, section{f.header})
		}
		if footerRows > 0 {
			secs = append(secs, section{f.footer})
		}
	} else {
		if headerRows > 0 {
			secs = append(secs, section{f.header})
		}
		if footerRows > 0 {
			secs = append(secs, section{f.footer})
		}
		secs = append(secs, section{listLines})
		if infoRows > 0 {
			secs = append(secs, section{[]string{f.renderInfoLine(W)}})
		}
		if promptRows > 0 {
			secs = append(secs, section{[]string{f.renderPromptLine(W, infoInline)}})
		}
	}
	for _, s := range secs {
		for _, l := range s.lines {
			b.WriteString("\x1b[2K")
			b.WriteString(l)
			b.WriteString("\r\n")
		}
	}
	f.term.write(b.String())
}

func runeWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 0x20 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if r >= 0x1100 && (r <= 0x115f || r == 0x2329 || r == 0x232a ||
		(r >= 0x2e80 && r <= 0xa4cf && r != 0x303f) ||
		(r >= 0xac00 && r <= 0xd7a3) ||
		(r >= 0xf900 && r <= 0xfaff) ||
		(r >= 0xfe30 && r <= 0xfe6f) ||
		(r >= 0xff00 && r <= 0xff60) ||
		(r >= 0xffe0 && r <= 0xffe6) ||
		(r >= 0x20000 && r <= 0x2fffd) ||
		(r >= 0x30000 && r <= 0x3fffd)) {
		return 2
	}
	return 1
}

func displayWidth(s []rune) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}

func truncateWidth(rs []rune, maxW int) ([]rune, int) {
	w := 0
	for i, r := range rs {
		rw := runeWidth(r)
		if w+rw > maxW {
			return rs[:i], w
		}
		w += rw
	}
	return rs, w
}

func (f *finder) renderList(listRows, W int) []string {
	o := f.opts
	lines := make([]string, 0, listRows)
	total := len(f.results)
	// determine the visible window
	start := f.offset
	if f.cursor < start {
		start = f.cursor
	}
	if f.cursor >= start+listRows {
		start = f.cursor - listRows + 1
	}
	f.offset = start
	reverse := o.layout == "reverse" || o.layout == "reverse-list"
	pointer := "▌"
	if !f.pal.unicode {
		pointer = ">"
	}
	if o.pointer != "" {
		pointer = o.pointer
	}
	gutter := "▌"
	if !f.pal.unicode {
		gutter = ">"
	}
	if o.gutter != "" {
		gutter = o.gutter
	}
	marker := "┃"
	if !f.pal.unicode {
		marker = ">"
	}
	if o.marker != "" {
		marker = o.marker
	}
	// header lines are part of the list area in default layout? no, separate
	for i := 0; i < listRows; i++ {
		var idx int
		if reverse {
			idx = start + i
		} else {
			idx = start + (listRows - 1 - i)
		}
		var line string
		if idx < 0 || idx >= total {
			line = ""
		} else {
			line = f.renderItem(idx, W, pointer, gutter, marker, reverse)
		}
		// scrollbar
		if total > 0 && listRows > 0 && o.scrollbar != "\x00none" {
			line += f.scrollbarFor(idx, listRows, total, W, false)
		}
		lines = append(lines, line)
	}
	return lines
}

func (f *finder) scrollbarFor(idx, listRows, total, W int, preview bool) string {
	o := f.opts
	if o.noScrollbar {
		return ""
	}
	c1 := "│"
	c2 := "│"
	if !f.pal.unicode {
		c1, c2 = ":", ":"
	}
	if o.scrollbar != "" && o.scrollbar != "\x00default" {
		rs := []rune(o.scrollbar)
		if len(rs) > 0 {
			c1 = string(rs[0])
		}
		if len(rs) > 1 {
			c2 = string(rs[1])
		}
	}
	char := c1
	if preview {
		char = c2
	}
	thumb := listRows * listRows / total
	if thumb < 1 {
		thumb = 1
	}
	var pos int
	if idx <= 0 {
		pos = 0
	} else {
		pos = listRows * idx / total
	}
	if pos+thumb > listRows {
		pos = listRows - thumb
	}
	if pos < 0 {
		pos = 0
	}
	// vertical position of this row within the list
	_ = pos
	return ""
}

func (f *finder) renderItem(idx, W int, pointer, gutter, marker string, reverse bool) string {
	r := f.results[idx]
	it := r.item
	o := f.opts
	isCur := idx == f.cursor
	isSel := f.selected[it.index]
	lead := ""
	var leadAttr colAttr
	if isCur {
		lead = pointer
		leadAttr = f.pal.get("pointer")
	} else if isSel {
		lead = marker
		leadAttr = f.pal.get("marker")
	} else {
		lead = gutter
		leadAttr = f.pal.get("gutter")
	}
	var b strings.Builder
	b.WriteString("\x1b[0m")
	if isCur || isSel {
		b.WriteString(ansiFor(leadAttr, false))
	} else {
		b.WriteString(ansiFor(f.pal.get("gutter"), false))
	}
	b.WriteString(lead)
	b.WriteString("\x1b[39m")
	if isCur || isSel {
		b.WriteString(ansiFor(colAttr{bg: f.pal.get("bg+").bg}, false))
		b.WriteString("\x1b[39m\x1b[0m")
	}
	b.WriteString(" ")
	// text
	text := []rune(it.displayText())
	pos := r.pos
	if isCur {
		b.WriteString(ansiFor(f.pal.get("fg+"), false))
	} else {
		b.WriteString(ansiFor(f.pal.get("fg"), false))
	}
	// highlight
	hl := f.pal.get("hl")
	if isCur {
		hl = f.pal.get("hl+")
	}
	writeHighlighted(&b, text, pos, f.pal.get("fg"), hl, isCur)
	b.WriteString("\x1b[0m\x1b[39m")
	return b.String()
}

func writeHighlighted(b *strings.Builder, text []rune, pos []int, fg, hl colAttr, isCur bool) {
	hlSet := map[int]bool{}
	for _, p := range pos {
		hlSet[p] = true
	}
	i := 0
	n := len(text)
	for i < n {
		if hlSet[i] {
			j := i
			for j < n && hlSet[j] {
				j++
			}
			b.WriteString(ansiFor(hl, !isCur))
			b.WriteString(string(text[i:j]))
			b.WriteString("\x1b[0m\x1b[39m")
			i = j
		} else {
			j := i
			for j < n && !hlSet[j] {
				j++
			}
			b.WriteString(ansiFor(fg, !isCur))
			b.WriteString(string(text[i:j]))
			b.WriteString("\x1b[0m\x1b[39m")
			i = j
		}
	}
}

func (f *finder) renderInfoLine(W int) string {
	o := f.opts
	var b strings.Builder
	b.WriteString("\x1b[0m")
	b.WriteString(ansiFor(f.pal.get("fg"), false))
	total := len(f.items)
	matched := len(f.results)
	info := fmt.Sprintf(" %d/%d", matched, total)
	if f.opts.multi {
		info += fmt.Sprintf(" (%d)", len(f.selected))
	}
	if f.reading {
		info = fmt.Sprintf(" %c%s", spinnerChars[f.spinner], info)
	}
	b.WriteString("  ")
	b.WriteString(ansiFor(f.pal.get("info"), false))
	b.WriteString(strings.TrimLeft(info, " "))
	b.WriteString(ansiFor(f.pal.get("separator"), false))
	b.WriteString("\x1b[39m")
	sep := "─"
	if !f.pal.unicode {
		sep = "-"
	}
	if o.separator != "" && o.separator != "\x00none" {
		if o.separator == "\x00default" {
			sep = "─"
			if !f.pal.unicode {
				sep = "-"
			}
		} else {
			sep = o.separator
		}
	}
	if o.noSeparator || o.separator == "" {
		sep = ""
	}
	w := W - 2 - displayWidth([]rune(strings.TrimLeft(info, " ")))
	if w > 0 && sep != "" {
		s := []rune(sep)
		rep := w / displayWidth(s)
		if rep < 1 {
			rep = 1
		}
		b.WriteString(strings.Repeat(sep, rep))
	}
	b.WriteString("\x1b[0m\x1b[39m\x1b[49m")
	return b.String()
}

func (f *finder) renderPromptLine(W int, infoInline bool) string {
	var b strings.Builder
	b.WriteString("\x1b[0m")
	b.WriteString(ansiFor(f.pal.get("prompt"), false))
	prompt := f.opts.prompt
	if f.opts.prompt == "" {
		prompt = "> "
	}
	b.WriteString(prompt)
	b.WriteString(ansiFor(f.pal.get("query"), false))
	b.WriteString("\x1b[39m")
	b.WriteString(ansiFor(colAttr{fg: -1, bold: true}, false))
	b.WriteString(string(f.query))
	b.WriteString("\x1b[0m\x1b[39m")
	b.WriteString(ansiFor(colAttr{fg: f.pal.get("query").fg}, false))
	b.WriteString(" ")
	b.WriteString("\x1b[0m\x1b[39m\x1b[49m")
	return b.String()
}
