		// read name
		j := i
		for j < len(s) && s[j] != '+' && s[j] != '(' && s[j] != '[' && s[j] != '{' && s[j] != '<' {
			j++
		}
		name := strings.TrimSpace(s[i:j])
		arg := ""
		if j < len(s) && s[j] != '+' {
			open := s[j]
			closer := map[byte]byte{'(': ')', '[': ']', '{': '}', '<': '>'}[open]
			k := j + 1
			depth := 1
			for k < len(s) && depth > 0 {
				if s[k] == open {
					depth++
				} else if s[k] == closer {
					depth--
					if depth == 0 {
						break
					}
				}
				k++
			}
			if k < len(s) {
				arg = s[j+1 : k]
				j = k + 1
			} else {
				arg = s[j+1:]
				j = len(s)
			}
		}
		if name != "" {
			out = append(out, action{name: name, arg: arg})
		}
		// skip '+' separators
		for j < len(s) && s[j] == '+' {
			j++
		}
		i = j
	}
	return out
}

