func (f *finder) handleKey(k key) bool {
	name := k.name
	if name == "" {
		name = keyNameForRune(k.chr)
	}
	// expect keys
	for _, exp := range f.expect {
		if exp == name {
			f.expectKey = exp
			return f.accept()
		}
	}
	if acts, ok := f.binds[name]; ok {
		for _, a := range acts {
			f.runAction(a, name)
			if f.done {
				return true
			}
		}
		return false
	}
	if acts, ok := defaultBinds[name]; ok {
		for _, a := range acts {
			f.runAction(a, name)
			if f.done {
				return true
			}
		}
		return false
	}
	if k.chr >= 32 {
		f.insertChar(k.chr)
		return false
	}
	return false
}

func (f *finder) runAction(a action, keyName string) {
	switch a.name {
	case "abort":
		f.abort()
	case "accept":
		f.accept()
	case "accept-non-empty":
		if len(f.results) == 0 {
			return
		}
		f.accept()
	case "accept-or-print-query":
		if len(f.results) == 0 {
			f.opts.printQuery = true
		}
		f.accept()
	case "up":
		f.moveCursor(-1)
	case "down":
		f.moveCursor(1)
	case "up-match":
		f.moveCursor(-1)
	case "down-match":
		f.moveCursor(1)
	case "page-up":
		f.moveCursor(-f.listRows())
	case "page-down":
		f.moveCursor(f.listRows())
	case "first":
		f.cursor = 0
	case "last":
		f.cursor = len(f.results) - 1
	case "toggle":
		f.toggle()
	case "toggle-in":
		f.moveCursor(-1)
		f.toggle()
	case "toggle-all":
		for _, r := range f.results {
			f.selected[r.item.index] = true
		}
	case "select":
		if f.cursor < len(f.results) {
			f.selected[f.results[f.cursor].item.index] = true
		}
	case "deselect":
		if f.cursor < len(f.results) {
			delete(f.selected, f.results[f.cursor].item.index)
		}
	case "toggle-sort":
		f.opts.sort = !f.opts.sort
		f.applyPattern()
	case "clear-query":
		f.query = nil
		f.qpos = 0
		f.applyPattern()
	case "change-query":
		f.query = []rune(a.arg)
		f.qpos = len(f.query)
		f.applyPattern()
	case "backward-char":
		if f.qpos > 0 {
			f.qpos--
		}
	case "forward-char":
		if f.qpos < len(f.query) {
			f.qpos++
		}
	case "beginning-of-line":
		f.qpos = 0
	case "end-of-line":
		f.qpos = len(f.query)
	case "backward-delete-char":
		if len(f.query) > 0 {
			if f.qpos == 0 {
				// backward-eof
				return
			}
			f.query = append(f.query[:f.qpos-1], f.query[f.qpos:]...)
			f.qpos--
			f.applyPattern()
		}
	case "backward-delete-char/eof":
		if len(f.query) == 0 {
			f.abort()
			return
		}
		if f.qpos > 0 {
			f.query = append(f.query[:f.qpos-1], f.query[f.qpos:]...)
			f.qpos--
			f.applyPattern()
		}
	case "delete-char":
		if f.qpos < len(f.query) {
			f.query = append(f.query[:f.qpos], f.query[f.qpos+1:]...)
			f.applyPattern()
		}
	case "delete-char/eof":
		if len(f.query) == 0 && f.qpos == 0 {
			f.abort()
			return
		}
		if f.qpos < len(f.query) {
			f.query = append(f.query[:f.qpos], f.query[f.qpos+1:]...)
			f.applyPattern()
		}
	case "unix-line-discard":
		if f.qpos > 0 {
			f.query = f.query[:0]
			f.qpos = 0
			f.applyPattern()
		}
	case "unix-word-rubout":
		f.killWord(true)
	case "backward-kill-word":
		f.killWord(false)
	case "kill-word":
		f.killWordFwd()
	case "backward-word":
		f.moveWord(-1)
	case "forward-word":
		f.moveWord(1)
	case "toggle-preview":
		// not implemented
	case "clear-screen":
		f.term.write("\x1b[2J")
	case "toggle-search":
		f.opts.disabled = !f.opts.disabled
		f.applyPattern()
	case "enable-search":
		f.opts.disabled = false
		f.applyPattern()
	case "disable-search":
		f.opts.disabled = true
		f.applyPattern()
	case "print":
		if a.arg != "" {
			if f.opts.print0 {
				fmt.Print(a.arg, "\x00")
			} else {
				fmt.Println(a.arg)
			}
		}
	case "bell":
		f.term.write("\a")
	case "jump":
		f.jumpMode = true
	case "execute", "execute-silent":
		f.execute(a.arg)
	case "become":
		f.become(a.arg)
	case "reload":
		f.reload()
	}
}

func (f *finder) insertChar(c rune) {
	q := make([]rune, 0, len(f.query)+1)
	q = append(q, f.query[:f.qpos]...)
	q = append(q, c)
	q = append(q, f.query[f.qpos:]...)
	f.query = q
	f.qpos++
	f.applyPattern()
}

func (f *finder) killWord(back bool) {
	if len(f.query) == 0 {
		return
	}
	p := f.qpos
	if back {
		for p > 0 && isSpaceRune(f.query[p-1]) {
			p--
		}
		for p > 0 && !isSpaceRune(f.query[p-1]) {
			p--
		}
		f.query = append(append([]rune{}, f.query[:p]...), f.query[f.qpos:]...)
		f.qpos = p
	} else {
		q := f.qpos
		for q < len(f.query) && isSpaceRune(f.query[q]) {
			q++
		}
		for q < len(f.query) && !isSpaceRune(f.query[q]) {
			q++
		}
		f.query = append(append([]rune{}, f.query[:f.qpos]...), f.query[q:]...)
	}
	f.applyPattern()
}

func (f *finder) killWordFwd() {
	p := f.qpos
	for p < len(f.query) && !isSpaceRune(f.query[p]) {
		p++
	}
	for p < len(f.query) && isSpaceRune(f.query[p]) {
		p++
	}
	f.query = append(append([]rune{}, f.query[:f.qpos]...), f.query[p:]...)
	f.applyPattern()
}

func (f *finder) moveWord(dir int) {
	if f.opts.filepathWord {
		// path separators
	}
	p := f.qpos
	if dir < 0 {
		for p > 0 && isSpaceRune(f.query[p-1]) {
			p--
		}
		for p > 0 && !isSpaceRune(f.query[p-1]) {
			p--
		}
	} else {
		for p < len(f.query) && isSpaceRune(f.query[p]) {
			p++
		}
		for p < len(f.query) && !isSpaceRune(f.query[p]) {
			p++
		}
	}
	f.qpos = p
}

func (f *finder) listRows() int {
	H := f.term.rows
	if f.opts.heightSpecified() {
		H = f.height
	}
	infoRows := 0
	if !strings.HasPrefix(f.opts.info, "inline") && f.opts.info != "hidden" {
		infoRows = 1
	}
	promptRows := 1
	if f.opts.noInput {
		promptRows = 0
	}
	headerRows := len(f.header)
	footerRows := len(f.footer)
	n := H - infoRows - promptRows - headerRows - footerRows
	if n < 1 {
		n = 1
	}
	return n
}

func (f *finder) moveCursor(d int) {
	n := len(f.results)
	if n == 0 {
		return
	}
	c := f.cursor + d
	if c < 0 {
		if f.opts.cycle {
			c = n - 1
		} else {
			c = 0
		}
	}
	if c >= n {
		if f.opts.cycle {
			c = 0
		} else {
			c = n - 1
		}
	}
	f.cursor = c
}

func (f *finder) toggle() {
	if f.cursor < 0 || f.cursor >= len(f.results) {
		return
	}
	it := f.results[f.cursor].item
	if f.selected[it.index] {
		delete(f.selected, it.index)
	} else {
		if f.opts.multiMax > 0 && len(f.selected) >= f.opts.multiMax {
			return
		}
		f.selected[it.index] = true
	}
}

func (f *finder) execute(cmd string) {
	f.executeWith(cmd, true)
}

func (f *finder) executeWith(cmd string, alt bool) {
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}
	c := exec.Command(shell, "-c", f.expandPlaceholders(cmd, false))
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	c.Run()
}

func (f *finder) become(cmd string) {
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}
	c := exec.Command(shell, "-c", f.expandPlaceholders(cmd, false))
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	err := c.Run()
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			if st, ok2 := ee.Sys().(syscall.WaitStatus); ok2 {
				f.exitCode = st.ExitStatus()
			}
		}
	}
	f.done = true
}

func (f *finder) expandPlaceholders(cmd string, _ bool) string {
	var cur string
	if f.cursor >= 0 && f.cursor < len(f.results) {
		cur = f.results[f.cursor].item.displayText()
	}
	return strings.ReplaceAll(cmd, "{}", "'"+strings.ReplaceAll(cur, "'", `'\'`)+"'")
}

func (f *finder) reload() {
	items, err := readItems(f.opts)
	if err != nil {
		return
	}
	f.items = items
	f.applyPattern()
}

