func parseBinds(specs []string) map[string][]action {
	m := map[string][]action{}
	for _, spec := range specs {
		for _, b := range splitBindSpec(spec) {
			idx := strings.Index(b, ":")
			if idx < 0 {
				continue
			}
			keys := b[:idx]
			rest := b[idx+1:]
			acts := parseActions(rest)
			for _, k := range strings.Split(keys, ",") {
				k = strings.TrimSpace(k)
				if k == "" {
					continue
				}
				m[k] = append(m[k], acts...)
			}
		}
	}
	return m
}

// splitBindSpec splits a --bind spec on commas that are not inside parentheses
// or other delimiters.
func splitBindSpec(s string) []string {
	var out []string
	depth := 0
	start := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '(', '{', '[', '<':
			depth++
		case ')', '}', ']', '>':
			depth--
		case ',', ':':
			if depth == 0 && s[i] == ',' {
				out = append(out, s[start:i])
				start = i + 1
			}
		}
	}
	out = append(out, s[start:])
	return out
}

func parseActions(s string) []action {
	var out []action
	i := 0
	for i < len(s) {
		// read name
		j := i
		for j < len(s) && s[j] != '+' && s[j] != '(' && s[j] != '[' && s[j] != '{' && s[j] != '<' {
			j++
		}
		name := strings.TrimSpace(s[i:j])
		arg := ""
		if j < len(s) && s[j] != '+' {
			open := s[j]
			closer := map[byte]byte{'(': ')', '[': ']', '{': '}', '<': '>'}[open]
			k := j + 1
			depth := 1
			for k < len(s) && depth > 0 {
				if s[k] == open {
					depth++
				} else if s[k] == closer {
					depth--
					if depth == 0 {
						break
					}
				}
				k++
			}
			if k < len(s) {
				arg = s[j+1 : k]
				j = k + 1
			} else {
				arg = s[j+1:]
				j = len(s)
			}
		}
		if name != "" {
			out = append(out, action{name: name, arg: arg})
		}
		// skip '+' separators
		for j < len(s) && s[j] == '+' {
			j++
		}
		i = j
	}
	return out
}

