func (f *finder) handleKey(k key) bool {
	name := k.name
	if name == "" {
		name = keyNameForRune(k.chr)
	}
	// expect keys
	for _, exp := range f.expect {
		if exp == name {
			f.expectKey = exp
			return f.accept()
		}
	}
	if acts, ok := f.binds[name]; ok {
		for _, a := range acts {
			f.runAction(a, name)
			if f.done {
				return true
			}
		}
		return false
	}
	if acts, ok := defaultBinds[name]; ok {
		for _, a := range acts {
			f.runAction(a, name)
			if f.done {
				return true
			}
		}
		return false
	}
	if k.chr >= 32 {
		f.insertChar(k.chr)
		return false
	}
	return false
}

